from pathlib import Path
import json, datetime, hashlib
O=Path(__file__).resolve().parents[1]
base=json.loads((O/'author/current20.base-goal-tuples.json').read_text()); IDS=base['goalIds']; G={g['id']:g for g in base['goals']}
cases=[];profiles=[];rationales=[]
def case(title_de,title_en,data_de,data_en,clauses,answers,criteria=None,practical=False):
    # Each paired clause is printed verbatim; each paired answer is its exact graded evidence.
    return dict(titleDe=title_de,titleEn=title_en,dataDe=data_de,dataEn=data_en,clauses=clauses,answers=answers,criteria=criteria or answers,practical=practical)
def add(n,archetype,expectations,axes,c1,c2,reason):
    gid=IDS[n-1]; ex=[dict(id=f'e{i+1}',essentialUnderstandingDe=e[0],essentialUnderstandingEn=e[1],observablePerformanceDe=e[2],observablePerformanceEn=e[3])for i,e in enumerate(expectations)]; briefs=[]
    for k,c in enumerate([c1,c2],1):
        cid=gid[:8]+f'-case-{k}'; td='\n'.join(f'{i+1}. {a[0]}'for i,a in enumerate(c['clauses']));te='\n'.join(f'{i+1}. {a[1]}'for i,a in enumerate(c['clauses']));ad='\n'.join(f'{i+1}. {a[0]}'for i,a in enumerate(c['answers']));ae='\n'.join(f'{i+1}. {a[1]}'for i,a in enumerate(c['answers']));rub=[]
        for i,(cl,ans) in enumerate(zip(c['clauses'],c['criteria'])):
            ids=[f'e{min(i+1,len(ex))}']; credit='observed-practical-execution-required' if c['practical'] and i==2 else 'written-explicit-task'
            rub.append(dict(criterionId=cid+f'-r{i+1}',expectationIds=ids,taskClauseDe=cl[0],taskClauseEn=cl[1],criterionDe=ans[0],criterionEn=ans[1],maximumPoints=2,partialCreditDe='1 Punkt für einen fachlich richtigen, ausdrücklich verlangten Teil; 2 für den vollständigen Nachweis; 0 für fehlenden oder falschen Nachweis. Ausführungspunkte setzen die benannte reale Beobachtung voraus.',partialCreditEn='1 point for a correct explicitly requested part; 2 for complete evidence; 0 for missing or wrong evidence. Execution credit requires the stated real observation.',creditBasis=credit,taskSpanDe={'start':td.index(cl[0]),'end':td.index(cl[0])+len(cl[0])},taskSpanEn={'start':te.index(cl[1]),'end':te.index(cl[1])+len(cl[1])}))
        row=dict(caseId=cid,goalId=gid,titleDe=c['titleDe'],titleEn=c['titleEn'],dataOrigin='Original invented idealized teaching data unless an explicitly attributed primary reference is named; no measured experiment or learner result',languageParity='Complete DE/EN data, task, answer, rubric and demand spans',dataDe=c['dataDe'],dataEn=c['dataEn'],taskDe=td,taskEn=te,modelAnswerDe=ad,modelAnswerEn=ae,expectationIds=[x['id']for x in ex],visualizationRequired=False,practicalExecutionRequired=c['practical'],executionClaim='No execution occurred. Supplied or synthetic observations cannot earn practical-execution credit.',rubric=rub,maximumPoints=sum(x['maximumPoints']for x in rub),optionalModelRemarksDe=[],optionalModelRemarksEn=[],gradingBoundary='Only explicitly demanded evidence earns credit. A case maps requested aspects, not automatic full profile completion. Observe practical actions separately; missing actual observation means those points remain unavailable.')
        cases.append(row);briefs.append(dict(id=cid,taskDemandDe=c['dataDe']+'\n'+td,taskDemandEn=c['dataEn']+'\n'+te,expectedPerformanceDe=ad,expectedPerformanceEn=ae,understandingFocusDe=' / '.join(x[0]for x in c['criteria']),understandingFocusEn=' / '.join(x[1]for x in c['criteria'])))
    profiles.append(dict(goalId=gid,profile=dict(archetype=archetype,expectations=ex,coverageExpectations=dict(requiredExpectationIds=[x['id']for x in ex],alternativeExpectationGroups=[],minimumIndependentDemonstrations=2,freshVariationRequired=True,independentTransferRequired=True),variationAxes=[dict(id=f'v{i+1}',textDe=a[0],textEn=a[1])for i,a in enumerate(axes)],applicationCaseBriefs=briefs)))
    rationales.append(dict(goalId=gid,atomicityCandidate=dict(status='needs_developer_review',semanticAtomic=None,reasonDe=reason),currentGoalBodyAndRequires='KEEP; proposed corrections are separate',independentVote=False))

add(1,'modeling',[
('Benzol besitzt einen planaren σ-Rahmen mit sechs überlappenden p-Orbitalen und sechs delokalisierten π-Elektronen.','Benzene has a planar sigma framework with six overlapping p orbitals and six delocalized pi electrons.','Verknüpft räumlichen Orbitalaufbau und Mesomeriedarstellung.','Connects the spatial orbital model to resonance notation.'),
('Stabilisierung wird auf derselben Stoffmengen- und Produktbasis energetisch verglichen; die Grenzformeln sind keine wechselnden Moleküle.','Stabilization is compared on the same amount and product basis; contributors are not alternating molecules.','Begründet Energiedifferenz und Modellgrenze anhand der Daten.','Justifies an energy difference and model limit from data.'),
('Eine Unterbrechung des zyklischen p-Systems vermindert Aromatizität und beeinflusst den Reaktionsweg.','Interrupting the cyclic p system removes aromaticity and affects the reaction route.','Überträgt die Modelle auf ein nichtaromatisches cyclisches System.','Transfers the models to a nonaromatic cyclic system.')], [('Orbitalgeometrie und energetische Basis','Orbital geometry and energy basis'),('Benzol versus unterbrochenes Ringsystem','Benzene versus an interrupted ring system')],
case('Benzol und Hydrierungsenergie','Benzene and hydrogenation energy','Erfundene Vergleichsdaten pro mol Edukt bei gleichen Bedingungen: Cyclohexen → Cyclohexan −120 kJ; Benzol + 3 H₂ → Cyclohexan −208 kJ. Ein hypothetisches lokalisiertes Cyclohexatrien hätte drei unabhängige C=C-Bindungen.','Invented comparison data per mole of reactant under identical conditions: cyclohexene → cyclohexane −120 kJ; benzene + 3 H₂ → cyclohexane −208 kJ. A hypothetical localized cyclohexatriene has three independent C=C bonds.',[
('Beschreibe den σ-Rahmen, die Orientierung der sechs p-Orbitale und die π-Elektronenzahl von Benzol; verknüpfe dies mit den zwei Kekulé-Grenzformeln.','Describe the sigma framework, orientation of six p orbitals and pi-electron count of benzene; connect this to its two Kekulé contributors.'),
('Berechne die modellierte Stabilisierung gegenüber drei unabhängigen Doppelbindungen und begründe das Vorzeichen auf gemeinsamer Produktbasis.','Calculate the modeled stabilization relative to three independent double bonds and justify its sign using the common product.'),
('Erkläre, warum die Kekulé-Grenzformeln weder ein Gleichgewicht noch drei fest lokalisierte π-Bindungen beschreiben.','Explain why the Kekulé contributors describe neither an equilibrium nor three permanently localized pi bonds.')],[
('Sechs sp²-C bilden den planaren σ-Rahmen; je ein p-Orbital steht senkrecht dazu und überlappt seitlich mit seinen Nachbarn. Sechs π-Elektronen sind ringweit delokalisiert; die zwei Kekulé-Formeln sind Elektronenbuchhaltung desselben Zustands.','Six sp² carbons form the planar sigma framework; one p orbital per carbon is perpendicular and overlaps sideways with its neighbors. Six pi electrons are delocalized over the ring; the two Kekulé formulas are electron bookkeeping for one state.'),
('3·(−120)=−360 kJ/mol; −208−(−360)=152 kJ/mol. Beim gleichen Endprodukt liegt Benzol etwa 152 kJ/mol tiefer als das hypothetische Edukt; deshalb wird weniger Energie frei. Die Zahl ist eine Näherung dieses Vergleichsmodells.','3·(−120)=−360 kJ/mol; −208−(−360)=152 kJ/mol. With the same final product benzene starts about 152 kJ/mol lower than the hypothetical reactant, so less energy is released. This value is an approximation of the comparison model.'),
('Es gibt keine Umwandlung zweier Isomere. Atomgerüst und σ-Bindungen bleiben gleich; die wirkliche π-Verteilung ist delokalisiert. Der Mesomeriepfeil ↔ verbindet Darstellungen, nicht zeitlich wechselnde Zustände.','There is no conversion between two isomers. The atomic framework and sigma bonds remain the same; the real pi distribution is delocalized. The resonance arrow ↔ links representations, not states alternating in time.')]),
case('Unterbrochener π-Ring','Interrupted pi ring','Benzol: sechs sp²-C. 1,3-Cyclohexadien: vier sp²-C und zwei sp³-C im Sechsring. Die beiden C=C-Bindungen des Diens liegen benachbart konjugiert; beide Moleküle sind ungeladen.','Benzene has six sp² carbons. 1,3-Cyclohexadiene has four sp² and two sp³ carbons in its six-membered ring. Its two double bonds form a conjugated segment; both molecules are uncharged.',[
('Zeige für beide Moleküle, wo p-Orbitale seitlich überlappen können, und bestimme die jeweilige π-Elektronenzahl.','Show where p orbitals can overlap sideways in each molecule and identify its pi-electron count.'),
('Entscheide mit Orbital- und Mesomeriemodell, welches System aromatisch stabilisiert ist; erkläre die Rolle der sp³-Zentren.','Use orbital and resonance models to decide which system is aromatically stabilized; explain the role of the sp³ centers.'),
('Begründe, warum Addition an das Dien energetisch nicht denselben Verlust zyklischer Aromatenstabilisierung verlangt wie Addition an Benzol.','Explain why addition to the diene does not require the same loss of cyclic aromatic stabilization as addition to benzene.')],[
('Benzol besitzt sechs durchgehend benachbarte p-Orbitale und sechs π-Elektronen. Das Dien hat vier p-Orbitale und vier π-Elektronen im offenen konjugierten Segment; die sp³-C liefern keine passenden p-Orbitale für den Ringschluss.','Benzene has six continuously adjacent p orbitals and six pi electrons. The diene has four p orbitals and four pi electrons in an open conjugated segment; its sp³ carbons do not provide matching p orbitals to close the cycle.'),
('Nur Benzol besitzt hier einen planaren, durchgehenden zyklischen π-Verbund mit sechs Elektronen. Die sp³-Zentren unterbrechen den Ring des Diens; lineare Konjugation ist keine Aromatizität.','Only benzene has a planar continuous cyclic pi network with six electrons here. The sp³ centers interrupt the diene ring; linear conjugation is not aromaticity.'),
('Das Dien verliert bei Addition gegebenenfalls lokale Konjugation, aber keine bereits vorhandene aromatische Ringstabilisierung. Benzol müsste bei Addition den zyklischen delokalisierten Zustand aufgeben; Substitution kann diesen nach Protonenabgabe wiederherstellen.','Addition may remove local conjugation in the diene but cannot remove aromatic ring stabilization that was never present. Benzene addition gives up its cyclic delocalized state; substitution can restore that state after proton loss.')]),'Ein Bindungsmodell mit energetischer Erklärung ist zusammenhängend; erweitertes Orbitalmodell und Mesomerie sind Darstellungen desselben Gegenstands. BY aaed261c enthält Reaktivität, wird aber tatsächlich an den Partner ac700167 mit ausdrücklicher Reaktivität gemappt. Keine f0f-Körpererweiterung ist dadurch begründet; die Partnerunion wird nicht freigegeben.')

add(2,'concept',[
('Mesomerie beschreibt ein einziges delokalisiertes Benzolmolekül.','Resonance describes one delocalized benzene molecule.','Verknüpft Grenzformeln mit gleichwertigen C–C-Bindungen.','Connects contributors to equivalent carbon-carbon bonds.'),
('Aromatische Stabilisierung erklärt die Bevorzugung von Substitution gegenüber dauerhaftem Aufbruch des π-Rings.','Aromatic stabilization explains the preference for substitution over permanent disruption of the pi ring.','Deutet Struktur- und Energiebefunde mit einer Modellgrenze.','Interprets structural and energy evidence with a model limit.')],[('Strukturmessung versus Reaktionsbefund','Structural evidence versus reaction evidence'),('Addition versus Substitution','Addition versus substitution')],
case('Sechs gleiche Bindungen','Six equal bonds','Idealisierte Unterrichtsdaten: Benzol hat sechs C–C-Abstände von 139 pm; Referenzwerte C–C 154 pm und C=C 134 pm. Alle Atome liegen in einer Ebene.','Idealized teaching data: benzene has six carbon-carbon distances of 139 pm; reference distances are 154 pm for C–C and 134 pm for C=C. All atoms lie in one plane.',[
('Zeichne beide neutralen Kekulé-Grenzformeln mit unverändertem Atomgerüst und erkläre, wie sie die sechs gleichen Bindungslängen modellieren.','Draw both neutral Kekulé contributors with an unchanged atomic framework and explain how they model six equal bond lengths.'),
('Beurteile die Behauptung „Die Einfach- und Doppelbindungen springen so schnell, dass man nur Mittelwerte sieht“ und begründe deine Korrektur.','Assess the claim “Single and double bonds jump so quickly that only averages are seen” and justify your correction.')],[
('Zwei Sechsringe mit alternierenden Doppelbindungen, im zweiten um eine Position versetzt, werden mit ↔ verbunden. Sie tragen keine Ladungen; H-Positionen bleiben gleich. Die wirkliche Elektronendichte ist ringweit verteilt, sodass alle C–C-Bindungen gleichwertig sind.','Two six-membered rings with alternating double bonds shifted by one position are joined by ↔. They have no charges and hydrogen positions stay fixed. The real electron density is distributed over the ring, making all C–C bonds equivalent.'),
('Die Behauptung verwechselt Darstellungen mit Molekülzuständen. Benzol ist ein Resonanzhybrid, kein zeitliches Gemisch zweier lokalisierter Formen. Die einheitlichen Abstände stützen die Delokalisierung; die beiden Bilder allein sind keine Bewegungssimulation.','The claim confuses representations with molecular states. Benzene is a resonance hybrid, not a temporal mixture of two localized forms. Uniform distances support delocalization; the pictures are not a simulation of moving bonds.')]),
case('Produkte mit oder ohne Aromatizität','Products with or without aromaticity','Für einen Papiervergleich werden zwei gedachte Wege angegeben: A ersetzt ein H am Benzol durch E und stellt danach den π-Ring wieder her; B bindet E und X dauerhaft an zwei benachbarte C, die dadurch sp³ werden. Keine realen Versuche.','A paper comparison supplies two hypothetical routes: A replaces one benzene H by E and then restores the pi ring; B permanently binds E and X at adjacent carbons, making them sp³. No real experiments.',[
('Vergleiche die π-Systeme der beiden Endprodukte und begründe, welcher Weg die besondere Benzolstabilisierung bewahrt.','Compare the pi systems of both final products and justify which route preserves benzene stabilization.'),
('Erkläre anhand des Mesomeriemodells, warum „Benzol besitzt drei normale Alken-Doppelbindungen“ keine tragfähige Reaktivitätsvorhersage ist.','Use the resonance model to explain why “benzene has three ordinary alkene double bonds” is not a sound reactivity prediction.')],[
('A liefert einen substituierten, wieder konjugierten Sechsring und bewahrt die aromatische Stabilisierung. In B unterbrechen zwei sp³-Zentren den p-Ring; das Produkt verliert diese Stabilisierung. Dies ist ein Stabilitätsargument, keine vollständige kinetische Berechnung.','A produces a substituted continuously conjugated six-membered ring and retains aromatic stabilization. In B two sp³ centers interrupt the p-orbital ring, removing that stabilization. This is a stability argument, not a complete kinetic calculation.'),
('Die drei eingezeichneten π-Bindungen sind Grenzformel-Buchhaltung. Die sechs π-Elektronen gehören zum delokalisierten Ring; dauerhaftes Addieren zerstört dessen Stabilisierung. Daher lässt sich Benzol nicht wie drei voneinander unabhängige Alkene behandeln.','The three drawn pi bonds are contributor bookkeeping. Six pi electrons belong to the delocalized ring; permanent addition destroys its stabilization. Benzene therefore cannot be treated as three independent alkenes.')]),'Ein Struktur-/Stabilitätsmodell. Abgrenzung zum ausführlicheren Orbitalziel f0f67a7a und zur Grenzformelbewertung b44f460b muss unabhängig geprüft werden.')

add(3,'concept',[
('Emission gibt Photonen ab; Absorption entzieht der einfallenden Strahlung bestimmte Wellenlängen.','Emission releases photons; absorption removes particular wavelengths from incident light.','Unterscheidet Energiefluss und Spektrensignal.','Distinguishes energy flow and spectral signals.'),
('Beobachtete Farbe hängt von der austretenden Strahlung und Beleuchtung ab.','Observed color depends on outgoing radiation and illumination.','Leitet Farbe in einer veränderten Beleuchtungssituation ab.','Predicts color under changed illumination.')],[('Selbstleuchten versus beleuchtetes Material','Self-emission versus illuminated material'),('Lichtquelle und Filter','Light source and filter')],
case('LED und Farbstofflösung','LED and dye solution','Idealisiert: Eine LED sendet im Dunkeln Licht bei 470 nm aus. Eine nicht fluoreszierende klare Lösung absorbiert aus weißem Licht vor allem 450–490 nm und lässt längere sichtbare Wellenlängen passieren.','Idealized: an LED emits 470 nm light in darkness. A clear nonfluorescent solution absorbs mostly 450–490 nm from white light and transmits longer visible wavelengths.',[
('Ordne beide Vorgänge Emission oder Absorption zu und beschreibe die Richtung des Energieübergangs zwischen Materie und Licht.','Classify both processes as emission or absorption and describe energy transfer between matter and light.'),
('Erkläre die blaue LED-Farbe und die näherungsweise gelbe Durchsichtfarbe der Lösung; sage begründet voraus, ob die Lösung im Dunkeln selbst leuchtet.','Explain the blue LED color and approximate yellow transmitted color of the solution; predict with reasons whether it glows in darkness.')],[
('Die LED emittiert: angeregte Materie gibt Energie als Photon ab. Die Lösung absorbiert: eingestrahlte Photonen übertragen Energie an Moleküle. Absorbierte blaue Photonen sind kein blaues Emissionssignal.','The LED emits: excited matter releases energy as photons. The solution absorbs: incoming photons transfer energy to molecules. Absorbed blue photons are not a blue emission signal.'),
('470 nm wird als blau wahrgenommen. Die Lösung entzieht dem weißen Licht den Blauanteil; durchgelassene Anteile ergeben näherungsweise gelb. Ohne Beleuchtung fehlt eingestrahltes Licht; bei ausgeschlossener Fluoreszenz und eigener Anregung leuchtet sie nicht.','470 nm is perceived as blue. The solution removes blue from white light; transmitted components appear approximately yellow. Without illumination there is no incident light; with fluorescence and independent excitation excluded it does not glow.')]),
case('Grüner Filter vor roter Quelle','Green filter before a red source','Modell: Eine Quelle emittiert nur 630 nm. Ein Filter lässt 520–560 nm passieren, absorbiert aber 630 nm vollständig; er fluoresziert nicht. Danach wird die rote Quelle durch eine 540-nm-Quelle ersetzt.','Model: a source emits only 630 nm. A filter transmits 520–560 nm but completely absorbs 630 nm and does not fluoresce. The red source is then replaced by a 540 nm source.',[
('Unterscheide den Emissionsvorgang der Quelle vom Absorptionsvorgang des Filters und erkläre, ob der Filter aus rotem Licht grünes Licht erzeugt.','Distinguish emission by the source from absorption by the filter and explain whether the filter produces green light from red light.'),
('Leite die Beobachtung hinter dem Filter für beide Quellen aus den Wellenlängenbereichen ab.','Predict the observation behind the filter for both sources using the wavelength ranges.')],[
('Die Quelle sendet Photonen ihrer vorgegebenen Wellenlänge aus. Der Filter nimmt Energie der 630-nm-Photonen auf; er erzeugt nach den Vorgaben keine 540-nm-Photonen. „Grün“ bedeutet hier Durchlassen, keine Farbkonversion.','The source emits photons at its specified wavelength. The filter takes up energy from 630 nm photons; under the conditions given it produces no 540 nm photons. “Green” describes transmission, not conversion.'),
('Mit 630 nm erscheint die Durchsicht dunkel, da die einzige eingestrahlte Wellenlänge absorbiert wird. Mit 540 nm erscheint sie grün, weil diese Wellenlänge im Durchlassbereich liegt.','With 630 nm the transmitted view is dark because the only incident wavelength is absorbed. With 540 nm it appears green because that wavelength lies in the passband.')]),'Eine Unterscheidung zweier Licht-Materie-Energieflüsse mit Farberklärung; keine eigenständige Emissionsspektroskopie oder Quantenrechnung.')

add(4,'modeling',[
('Die Oberfläche reflektiert die nicht absorbierten Anteile der Beleuchtung; Farben sind keine Stoffetiketten unabhängig vom Licht.','A surface reflects nonabsorbed illumination components; color is not independent of the light.','Verknüpft Spektralanteile von Einfall, Absorption und Reflexion.','Connects spectral components of incident, absorbed and reflected light.'),
('Eine eingeschränkte Beleuchtung verändert die reflektierte Farbe.','Restricted illumination changes reflected color.','Überträgt auf anders zusammengesetztes einfallendes Licht.','Transfers to different incident spectra.')],[('Weißlicht und monochromatische Beleuchtung','White and monochromatic illumination'),('Reflexionsdaten und Farbvergleich','Reflectance data and color comparison')],
case('Blauer Stoff unter gelbem Licht','Blue fabric in yellow light','Ideales undurchsichtiges Gewebe reflektiert 430–480 nm stark, absorbiert 550–650 nm fast vollständig. Weißlicht enthält beide Bereiche; die zweite Lampe liefert nur 590 nm. Emission und Transmission sind ausgeschlossen.','An ideal opaque fabric strongly reflects 430–480 nm and almost completely absorbs 550–650 nm. White light contains both ranges; a second lamp supplies only 590 nm. Emission and transmission are excluded.',[
('Erkläre die Farbe unter Weißlicht mit absorbierten und reflektierten Wellenlängen, ohne absorbiertes Licht als sichtbare Stofffarbe zu deuten.','Explain the color under white light using absorbed and reflected wavelengths, without treating absorbed light as the visible fabric color.'),
('Sage die Erscheinung unter 590-nm-Licht voraus und begründe sie mit dem verfügbaren Einfallsspektrum.','Predict its appearance under 590 nm illumination and justify it using the available incident spectrum.')],[
('Das Gewebe reflektiert den Blauanteil 430–480 nm und absorbiert längere Anteile; das Auge erhält überwiegend blaues Licht. Die absorbierten gelb-roten Anteile gelangen nicht als Reflexionslicht zum Auge.','The fabric reflects the blue 430–480 nm component and absorbs longer wavelengths; the eye receives mainly blue light. Absorbed yellow-red components do not reach the eye as reflection.'),
('Es erscheint sehr dunkel. 590 nm wird fast vollständig absorbiert; die Lampe liefert keine blauen Photonen, die das Gewebe reflektieren könnte.','It appears very dark. 590 nm is almost completely absorbed, and the lamp supplies no blue photons for the fabric to reflect.')]),
case('Zwei rote Muster unterscheiden','Distinguishing two red samples','Erfundene Reflexionsanteile bei 450/550/650 nm: Muster A 5/5/80 %, Muster B 5/40/80 %. Weißlicht hat gleiche Intensität in den drei Modellbändern; die zweite Beleuchtung enthält nur 550 nm.','Invented reflectance at 450/550/650 nm: sample A 5/5/80%, sample B 5/40/80%. White light has equal intensity in the three model bands; a second light contains only 550 nm.',[
('Vergleiche die reflektierten Weißlichtanteile beider Muster und erkläre, warum ihre Farben trotz gleicher Rotreflexion verschieden sein können.','Compare both samples’ reflected white-light components and explain why colors may differ despite equal red reflection.'),
('Entscheide, welches Muster unter 550 nm heller wirkt, und begründe die Entscheidung; nenne die Grenze einer exakten Farbbezeichnung aus nur drei Bändern.','Decide which sample looks brighter at 550 nm and justify it; state the limit of assigning an exact color name from only three bands.')],[
('A reflektiert fast nur Rot und wirkt rot. B reflektiert zusätzlich deutlich Grün, daher kann es gelblicher wirken. Gleiche Rotanteile garantieren keine gleiche Farbe, weil auch die übrigen Anteile zählen.','A reflects mainly red and appears red. B additionally reflects much more green and may therefore look more yellowish. Equal red components do not guarantee equal color because the other components matter.'),
('B ist heller: 40 % statt 5 % des angebotenen Grünlichts werden reflektiert. Ein vollständiges Spektrum und die Wahrnehmungsbedingungen fehlen; eine exakte Farbkoordinate oder Farbbezeichnung ist damit nicht festgelegt.','B is brighter because it reflects 40% rather than 5% of the offered green light. The full spectrum and perception conditions are missing, so an exact color coordinate or name is not fixed.')]),'Ein Reflexionsmodell; Transmission ist in den Fällen ausdrücklich ausgeschlossen, um Körper und transparente Lösungen nicht zu vermischen.')

add(5,'modeling',[
('Donor und Akzeptor beeinflussen ein gekoppeltes π-System; der Effekt hängt von Stellung und Kopplung ab.','Donor and acceptor groups affect a coupled pi system; the effect depends on position and coupling.','Identifiziert Gruppen und verknüpft elektronischen Effekt mit Spektren.','Identifies groups and connects electronic effects to spectra.'),
('Protonierung oder unterbrochene Konjugation kann einen Donoreffekt verändern; eine Rotverschiebung ist keine universelle Gruppenregel.','Protonation or interrupted conjugation can alter donation; a red shift is not a universal group rule.','Begründet einen veränderten Übergang anhand konkreter Bedingungen.','Explains a changed transition under specific conditions.')],[('Donorprotonierung und Spektraländerung','Donor protonation and spectrum change'),('Konjugation versus sp³-Unterbrechung','Conjugation versus sp³ interruption')],
case('Protonierter Aminodonor','Protonated amino donor','Papiermodell eines planaren Donor–π–Akzeptor-Farbstoffs: para-(CH₃)₂N–C₆H₄–CH=CH–C₆H₄–NO₂. Gleicher Lösungsmittelzustand; λmax neutral 510 nm, nach Protonierung des Aminostickstoffs 430 nm. Die Nitrogruppe bleibt unverändert.','Paper model of a planar donor–pi–acceptor dye: para-(CH₃)₂N–C₆H₄–CH=CH–C₆H₄–NO₂. Same solvent conditions; neutral λmax 510 nm and 430 nm after protonation at the amino nitrogen. The nitro group remains unchanged.',[
('Kennzeichne Donor und Akzeptor im neutralen Molekül und begründe die Kopplung über das π-System.','Identify donor and acceptor in the neutral molecule and explain coupling through the pi system.'),
('Erkläre die Änderung des Aminodonors bei Protonierung und ordne die gemessene Verschiebungsrichtung sowie die Änderung der Übergangsenergie zu.','Explain the amino donor change on protonation and identify the stated shift direction and transition-energy change.')],[
('–N(CH₃)₂ kann sein freies Elektronenpaar in das gekoppelte π-System einspeisen (+M); –NO₂ zieht über Mesomerie Elektronendichte ab (−M). Die sp²-Brücke ermöglicht Kopplung der beiden Enden.','–N(CH₃)₂ can donate its lone pair into the coupled pi system (+M); –NO₂ withdraws electron density through resonance (−M). The sp² bridge couples the two ends.'),
('Nach H⁺-Bindung ist das Paar in einer N–H-Bindung gebunden; der neutrale +M-Donor steht nicht mehr so zur Verfügung. 510→430 nm ist hypsochrom; nach ΔE=hc/λ steigt die Übergangsenergie. Das erklärt diesen angegebenen Fall, keine universelle Regel für alle protonierten Farbstoffe.','After H⁺ bonding the pair forms the N–H bond, so the neutral +M donor is no longer available in the same way. 510→430 nm is hypsochromic; ΔE=hc/λ increases. This explains the supplied case rather than a universal rule for all protonated dyes.')]),
case('Gleiche Endgruppen, andere Brücke','Same end groups, different bridge','Zwei idealisierte Moleküle besitzen dieselben Amino-Donor- und Nitro-Akzeptor-Endgruppen. A hat eine planare –CH=CH–Brücke und λmax 500 nm. B hat –CH₂–CH₂– als Brücke und λmax 330 nm; Konzentration und Lösungsmittel sind gleich.','Two idealized molecules have the same amino donor and nitro acceptor end groups. A has a planar –CH=CH– bridge and λmax 500 nm. B has a –CH₂–CH₂– bridge and λmax 330 nm; concentration and solvent are equal.',[
('Erkläre, welche Brücke Donor und Akzeptor mesomer koppelt, und begründe die Unterbrechung bei der anderen.','Explain which bridge couples donor and acceptor by resonance and why the other interrupts it.'),
('Verknüpfe die zwei Absorptionsmaxima mit Übergangsenergie und sichtbarer Farbigkeit; beurteile die Aussage „Eine Nitrogruppe macht jedes Molekül farbig“.','Connect both absorption maxima to transition energy and visible color; assess the claim “A nitro group makes every molecule colored”.')],[
('A besitzt benachbarte p-Orbitale über die sp²-Brücke. Bei B unterbrechen sp³-C die durchgehende Konjugation; die Endgruppen allein bilden kein langes gekoppeltes π-System.','A has adjacent p orbitals through its sp² bridge. In B sp³ carbons interrupt continuous conjugation; end groups alone do not make a long coupled pi system.'),
('500 nm liegt im sichtbaren Bereich und entspricht einer kleineren ΔE als 330 nm im UV. A kann durch sichtbare Absorption farbig sein; B wäre im gegebenen Modell ohne weitere sichtbare Banden farblos. Die Nitrogruppe allein garantiert keine sichtbare Absorption.','500 nm is visible and corresponds to a smaller ΔE than ultraviolet 330 nm. A can be colored by visible absorption; B would be colorless in the given model without other visible bands. A nitro group alone does not guarantee visible absorption.')]),'Ein Struktur-Farbe-Zusammenhang mit spezifizierter Konjugation; Energieinterpretation und funktionelle Gruppen sind Teile derselben Erklärung.')

add(6,'data',[
('Ein Absorptionsspektrum enthält Wellenlängenlage und Intensität unter definierten Bedingungen.','An absorption spectrum contains wavelength position and intensity under defined conditions.','Bestimmt Maxima, Banden und sinnvolle Messbedingungen.','Identifies maxima, bands and meaningful measurement conditions.'),
('Absorbanz hängt auch von Konzentration und Weglänge ab; Spektrenvergleich darf Intensität nicht mit Bandverschiebung verwechseln.','Absorbance also depends on concentration and path length; intensity changes are distinct from spectral shifts.','Vergleicht veränderte Proben und begrenzt die Schlussfolgerung.','Compares changed samples and limits the inference.')],[('Wellenlängenlage versus Verdünnung','Wavelength position versus dilution'),('Überlagerung und Referenzspektren','Superposition and reference spectra')],
case('Verdünnen verschiebt kein Maximum','Dilution does not shift the maximum','Erfundene Absorbanz bei 420/460/500/540/580 nm: Probe A 0,10/0,40/0,90/0,45/0,10; halb konzentriertes B 0,05/0,20/0,45/0,225/0,05. Gleiche 1-cm-Küvette, Lösungsmittel und temperaturstabiler Farbstoff ohne Aggregation.','Invented absorbance at 420/460/500/540/580 nm: sample A 0.10/0.40/0.90/0.45/0.10; half-concentration B 0.05/0.20/0.45/0.225/0.05. Same 1 cm cuvette and solvent, stable temperature and nonaggregating dye.',[
('Bestimme für beide Proben das tabellierte Maximum und beschreibe Lage sowie Intensitätsänderung getrennt.','Identify both tabulated maxima and describe position and intensity changes separately.'),
('Erkläre die Absorbanzänderung mit A=εcl und beurteile, ob die Tabelle eine Änderung der molekularen Übergangsenergie belegt.','Explain the absorbance change using A=εcl and assess whether the table proves a change of molecular transition energy.')],[
('Beide tabellierten Maxima liegen bei 500 nm. Amax sinkt von 0,90 auf 0,45; die Bandenlage bleibt im Raster gleich. Das exakte Maximum zwischen Stützstellen ist nicht bestimmt.','Both tabulated maxima are at 500 nm. Amax decreases from 0.90 to 0.45; the band position stays the same on the grid. An exact maximum between data points is not determined.'),
('Bei gleicher ε und l halbiert halbes c die Absorbanz. Eine Intensitätsänderung bei gleicher λmax belegt keine veränderte ΔE; die Daten passen zur Verdünnung desselben Farbstoffs.','At equal ε and l, halving c halves absorbance. An intensity change with unchanged λmax does not establish a changed ΔE; the data fit dilution of the same dye.')]),
case('Mischung aus zwei Referenzfarbstoffen','Mixture of two reference dyes','Ideales additives Modell gleicher Küvetten: bei 450/550/650 nm hat Referenz X A=0,8/0,1/0,0, Y A=0,0/0,1/0,7. Mischung M A=0,8/0,2/0,7. Rauschen ±0,02; keine chemische Wechselwirkung.','Ideal additive model with identical cuvettes: at 450/550/650 nm reference X has A=0.8/0.1/0.0, Y has A=0.0/0.1/0.7. Mixture M has A=0.8/0.2/0.7. Noise is ±0.02; no chemical interaction.',[
('Prüfe an allen drei Wellenlängen, ob M als Summe von X und Y erklärbar ist, und ordne die zwei starken Absorptionsbereiche zu.','Check at all three wavelengths whether M can be explained as the sum of X and Y and assign its two strong absorption regions.'),
('Wähle je eine geeignete Wellenlänge zum möglichst getrennten Nachweis von X und Y; begründe die Wahl und nenne eine Grenze der eindeutigen Stoffidentifikation aus drei Stützstellen.','Choose one wavelength for each nearly separate detection of X and Y; justify both choices and state one limit to unambiguous identification from three data points.')],[
('0,8+0,0=0,8; 0,1+0,1=0,2; 0,0+0,7=0,7. M entspricht der Summe. 450 nm wird X, 650 nm Y zugeordnet; die Mitte enthält Beiträge beider.','0.8+0.0=0.8; 0.1+0.1=0.2; 0.0+0.7=0.7. M matches the sum. 450 nm is assigned to X and 650 nm to Y; the middle contains both contributions.'),
('450 nm für X und 650 nm für Y, weil die jeweils andere Referenz dort im Modell nicht absorbiert. Drei Punkte schließen weitere Farbstoffe mit denselben Werten nicht aus; ein vollständigeres Spektrum oder weiterer Nachweis wäre nötig.','450 nm for X and 650 nm for Y because the other reference does not absorb there in this model. Three points cannot exclude other dyes with the same values; a fuller spectrum or another identification method is needed.')]),'Eine Datenauswertung mit begrenzter Identifikation; Fotometrie ist keine chromatografische Rf-Auswertung. BB/BE Chromatografiealias bleibt offen.')

add(7,'procedure',[
('Azokupplung ist elektrophile aromatische Substitution am aktivierten Kupplungspartner; Diazotierung und Kupplung sind getrennte Schritte.','Azo coupling is electrophilic aromatic substitution on the activated partner; diazotization and coupling are separate steps.','Stellt Teilchenschritte, Ladungen und Elektronenpaarwege der Azobildung dar.','Represents particle steps, charges and electron-pair movement in azo formation.'),
('Eine Triphenylmethanroute koppelt zweimal einen aktivierten Aromaten an ein Carbonylkohlenstoffzentrum und erzeugt den Farbstoff erst durch Oxidation der Leukoverbindung.','A triphenylmethane route attaches two activated arenes to a carbonyl carbon and produces the dye only after oxidizing the leuco compound.','Stellt die Kondensationsschritte und ladungsbilanzierte Oxidation dar.','Represents condensation steps and charge-balanced oxidation.')],[('Kupplungspartner und Ladungsbilanz','Coupling partner and charge balance'),('Azo-Synthese versus Triarylmethan-Kondensation','Azo synthesis versus triarylmethane condensation')],
case('Phenolkupplung und Leukomalachitgrün','Phenol coupling and leucomalachite green','Nur Papiermechanismen, keine Ausführung. Azo: Ph–N≡N⁺ und C₆H₅OH unter Bedingungen mit aktivem Phenol; das Produkt ist para-HO–C₆H₄–N=N–Ph. Triarylmethan: Ph–CHO + 2 Ar–H, Ar–H=N,N-Dimethylanilin, Angriff jeweils para zum –N(CH₃)₂. Säurekatalyse liefert Ph–CH(Ar)₂; anschließende Oxidation liefert [Ph–C(Ar)₂]⁺.','Paper mechanisms only, no execution. Azo: Ph–N≡N⁺ and C₆H₅OH under conditions with reactive phenol; the product is para-HO–C₆H₄–N=N–Ph. Triarylmethane: Ph–CHO + 2 Ar–H, with Ar–H=N,N-dimethylaniline and each attack para to –N(CH₃)₂. Acid catalysis gives Ph–CH(Ar)₂; oxidation then gives [Ph–C(Ar)₂]⁺.',[
('Stelle für die Azokupplung Elektronenpaarpfeile vom Ring zum terminalen Diazoniumnitrogen, die Verringerung von N≡N zu N=N, den σ-Komplex und die rearomatisierende Protonenabgabe dar; bilanziere die Gesamtladung.','Show electron-pair arrows from the ring to terminal diazonium nitrogen, reduction of N≡N to N=N, the sigma complex and rearomatizing proton loss; balance overall charge.'),
('Stelle für Ph–CHO die Carbonylprotonierung, zwei para-Angriffe von Ar–H mit Wasserabspaltung zwischen ihnen und die jeweilige Rearomatisierung dar; schreibe Kondensationsgleichung und Oxidationshalbreaktion.','Show carbonyl protonation, two para attacks by Ar–H with water loss between them and each rearomatization; write the condensation equation and oxidation half-equation.')],[
('Ein Ring-π-Paar greift das terminale N von Ph–N≡N⁺ an; ein N≡N-π-Paar wird auf das an Ph gebundene N verschoben. Es entsteht ein positiv geladener Ring-σ-Komplex mit Ph–N=N–C-Bindung. Eine Base nimmt H⁺ am angegriffenen C ab; das C–H-Paar stellt die Ring-π-Bindung wieder her. PhN₂⁺ + C₆H₅OH → Ph–N=N–C₆H₄–OH + H⁺: +1 auf beiden Seiten.','A ring pi pair attacks the terminal N of Ph–N≡N⁺; one N≡N pi pair moves onto the N bound to Ph. This gives a positively charged ring sigma complex with a Ph–N=N–C bond. A base removes H⁺ at the attacked carbon; its C–H pair restores the ring pi bond. PhN₂⁺ + C₆H₅OH → Ph–N=N–C₆H₄–OH + H⁺ has +1 on both sides.'),
('O-Protonierung ergibt Ph–CH=OH⁺. Ring-π→Carbonyl-C und C=O-π→O erzeugen den ersten Ring-σ-Komplex; Deprotonierung liefert Ph–CH(OH)–Ar. OH-Protonierung und C–O→O lassen H₂O abgehen: Ph–CH(Ar)⁺. Zweiter Ring-π-Angriff und Ring-H⁺-Abgabe liefern Ph–CH(Ar)₂. Gesamt: PhCHO+2 ArH→PhCH(Ar)₂+H₂O. Oxidation: PhCH(Ar)₂→[PhC(Ar)₂]⁺+H⁺+2e⁻ (Ladung 0=+1+1−2).','O protonation gives Ph–CH=OH⁺. Ring pi→carbonyl C and C=O pi→O produce the first ring sigma complex; deprotonation gives Ph–CH(OH)–Ar. OH protonation and C–O→O release H₂O, giving Ph–CH(Ar)⁺. A second ring pi attack and ring H⁺ loss give Ph–CH(Ar)₂. Overall: PhCHO+2 ArH→PhCH(Ar)₂+H₂O. Oxidation: PhCH(Ar)₂→[PhC(Ar)₂]⁺+H⁺+2e⁻, with 0=+1+1−2 charge.')]),
case('Nitro-diazonium und anderer Triarylmethanrest','Nitro diazonium and a different triarylmethane residue','Papiermodell: p-NO₂–C₆H₄–N₂⁺ koppelt an N,N-Dimethylanilin para zum Aminodonor. Eine zweite Route verwendet p-CH₃–C₆H₄–CHO + 2 N,N-Dimethylanilin. Bezeichne p-CH₃–C₆H₄ als R und den para-gekoppelten Dimethylaminophenylrest als Ar. Gegenionen sind Zuschauer; keine Stoffe werden hergestellt.','Paper model: p-NO₂–C₆H₄–N₂⁺ couples to N,N-dimethylaniline para to its amino donor. Another route uses p-CH₃–C₆H₄–CHO + 2 N,N-dimethylaniline. Write R for p-CH₃–C₆H₄ and Ar for the para-attached dimethylaminophenyl residue. Counterions are spectators; no substances are made.',[
('Zeichne den Azokupplungsmechanismus mit Elektronenpaarpfeilen, N=N-Verknüpfung, σ-Komplex-Ladung und Deprotonierung; erkläre, warum vollständige Protonierung des Aminodonors die Kupplung erschwert.','Draw azo coupling with electron-pair arrows, N=N linkage, sigma-complex charge and deprotonation; explain why complete protonation of the amino donor hinders coupling.'),
('Übertrage die säurekatalysierte Carbonylroute auf R–CHO: zeige beide Ringangriffe, Protonierungs- und Wasserabspaltungsschritte sowie die Oxidation von R–CH(Ar)₂; unterscheide Leukoverbindung und Farbstoffkation.','Transfer the acid-catalyzed carbonyl route to R–CHO: show both ring attacks, protonation and water-loss steps and oxidation of R–CH(Ar)₂; distinguish the leuco compound from the dye cation.')],[
('π-Paar des Dimethylanilinrings→terminales Diazonium-N; N≡N-π-Paar→inneres N. Positiver σ-Komplex→H⁺-Abgabe mit C–H-Paar→Ring-π. Produkt p-NO₂–C₆H₄–N=N–C₆H₄–N(CH₃)₂, insgesamt Diazoniumpartner+ArH→Azofarbstoff+H⁺. Protoniertes –N⁺H(CH₃)₂ hat kein verfügbares freies Paar für den +M-Effekt, daher weniger aktivierter Ring.','Dimethylaniline ring pi pair→terminal diazonium N; N≡N pi pair→inner N. Positive sigma complex→H⁺ loss with C–H pair→ring pi. Product: p-NO₂–C₆H₄–N=N–C₆H₄–N(CH₃)₂; overall diazonium partner+ArH→azo dye+H⁺. Protonated –N⁺H(CH₃)₂ lacks an available lone pair for +M donation, so the ring is less activated.'),
('R–CH=OH⁺ wird vom Ring-π-Paar angegriffen, C=O-π→O; nach Ringdeprotonierung entsteht R–CH(OH)–Ar. OH-Protonierung, H₂O-Abgabe und zweiter Ringangriff ergeben nach erneuter Ringdeprotonierung R–CH(Ar)₂. RCHO+2ArH→RCH(Ar)₂+H₂O. RCH(Ar)₂→[RC(Ar)₂]⁺+H⁺+2e⁻ ist ladungsbilanziert. Der sp³-Leukokohlenstoff unterbricht die ausgedehnte Kopplung; das sp²-Kation ermöglicht donorstabilisierte delokalisierte Formen.','Ring pi attacks R–CH=OH⁺ while C=O pi moves to O; ring deprotonation gives R–CH(OH)–Ar. OH protonation, water loss and second ring attack give R–CH(Ar)₂ after another ring deprotonation. RCHO+2ArH→RCH(Ar)₂+H₂O. RCH(Ar)₂→[RC(Ar)₂]⁺+H⁺+2e⁻ balances charge. The sp³ leuco carbon interrupts extended coupling; the sp² cation supports donor-stabilized delocalized contributors.')]),'Zwei eigenständige Synthesemechanismen sind im Körper gemeinsam gefordert. Die Autorin behält das Ziel, empfiehlt aber echte unabhängige Atomaritätsprüfung; vollständige P-Abdeckung ersetzt diese nicht. BB/BE Strukturquelle ist kein Syntheseoperator.')

add(8,'modeling',[
('Färbereignung entsteht aus konkreten Farbstoff-Faser-Wechselwirkungen und Bedingungen.','Dye suitability arises from specific dye-fiber interactions and conditions.','Ordnet Ladungen, Wasserstoffbrücken, Dispersion oder kovalente Fixierung zu.','Assigns charges, hydrogen bonding, dispersion or covalent fixation.'),
('Löslichkeit, Bindungsstärke und Waschbeständigkeit müssen zusammen beurteilt werden.','Solubility, interaction strength and wash resistance must be judged together.','Begründet eine materialbezogene Auswahl mit Grenzen.','Justifies a material-specific choice with limits.')],[('Proteinfasern versus Cellulose','Protein fibers versus cellulose'),('Kovalente Fixierung versus Einlagerung','Covalent fixation versus entrapment')],
case('Anionischer Farbstoff auf Wolle','Anionic dye on wool','Modell im sauren Färbebad: Wollprotein trägt –NH₃⁺-Gruppen; Baumwollcellulose überwiegend ungeladene –OH-Gruppen. Farbstoff D besitzt zwei –SO₃⁻-Gruppen und H-Brücken-Akzeptoren. Beide Proben werden gleich gespült; keine kovalente Reaktion.','Model in an acidic dye bath: wool protein carries –NH₃⁺ groups; cotton cellulose has mostly uncharged –OH groups. Dye D has two –SO₃⁻ groups and hydrogen-bond acceptors. Both samples are rinsed equally; no covalent reaction.',[
('Beschreibe die elektrostatischen und möglichen Wasserstoffbrücken-Wechselwirkungen von D mit beiden Fasern; unterscheide sie von kovalenter Bindung.','Describe electrostatic and possible hydrogen-bond interactions of D with both fibers; distinguish them from covalent bonding.'),
('Beurteile die bevorzugte Eignung für Wolle gegenüber Baumwolle unter den angegebenen Bedingungen und nenne eine Grenze der Waschbeständigkeitsvorhersage.','Assess preferred suitability for wool rather than cotton under these conditions and state one limit of predicting wash resistance.')],[
('D⁻-Gruppen werden von Woll–NH₃⁺ elektrostatisch angezogen. Zusätzlich sind H-Brücken zwischen geeigneten Faser-Donoren und D-Akzeptoren möglich. Cellulose bietet –OH für H-Brücken, aber hier keine positiven Fixierstellen. Keine der Wechselwirkungen ist eine neu gebildete kovalente Farbstoff-Faser-Bindung.','D anionic groups are electrostatically attracted to wool –NH₃⁺. Hydrogen bonds may also form between suitable fiber donors and dye acceptors. Cellulose offers –OH groups for hydrogen bonding but no positive fixation sites here. Neither interaction is a newly formed covalent dye-fiber bond.'),
('Wolle besitzt hier zusätzliche ionische Anziehung und ist daher günstiger für D. Dies ist keine Garantie: konkrete Bindungsstärke, Farbstoffgröße, pH des Waschbads oder Konkurrenz durch Wasser fehlen. Die bloße Anzahl von –OH-Gruppen belegt keine stärkere Fixierung an Baumwolle.','Wool provides additional ionic attraction and is favored for D here. This is not a guarantee: actual interaction strength, dye size, wash-bath pH or competition from water are unknown. Merely counting –OH groups does not establish stronger cotton fixation.')]),
case('Reaktivfarbstoff oder Dispersionsfarbstoff','Reactive dye or disperse dye','Idealisiert: Cellulose–O⁻ kann am elektrophilen Triazin-C eines Reaktivfarbstoffs mit Cl-Abgang substituieren: Cell–O–Triazin–D. Polyester besitzt unter den angegebenen Bedingungen keine entsprechenden reaktiven Gruppen; ein neutraler wenig wasserlöslicher Dispersionsfarbstoff lagert sich durch Dispersion und hydrophobe Affinität ein.','Idealized: cellulose–O⁻ can substitute at electrophilic triazine C of a reactive dye with chloride leaving, giving Cell–O–Triazine–D. Polyester has no corresponding reactive groups under the stated conditions; a neutral poorly water-soluble disperse dye is taken up through dispersion and hydrophobic affinity.',[
('Ordne beide Fixierungsmodelle den Fasern zu und erkläre den Unterschied zwischen kovalenter Reaktion und intermolekularer Einlagerung.','Assign both fixation models to the fibers and explain covalent reaction versus intermolecular uptake.'),
('Beurteile, warum ein stark wasserlöslicher ionischer Farbstoff ohne reaktive Gruppe für diesen Polyester ungünstig ist, und begrenze die Behauptung „kovalent bedeutet immer unveränderliche Farbe“.','Assess why a highly water-soluble ionic dye without a reactive group is unfavorable for this polyester and limit the claim “covalent always means unchangeable color”.')],[
('Reaktivfarbstoff passt zum angegebenen Cellulose-Nukleophil: neue Cell–O–C-Bindung mit Cl⁻-Abgang. Der Dispersionsfarbstoff wird ohne neue kovalente Bindung im Polyester aufgenommen. Beide Modelle beruhen auf verschiedenen Stoffeigenschaften.','The reactive dye fits the given cellulose nucleophile: a new Cell–O–C bond forms with Cl⁻ departure. The disperse dye enters polyester without a new covalent bond. The models rely on different material properties.'),
('Der ionische Farbstoff bevorzugt Wasser und hat in diesem Modell keine günstige Fixierroute am Polyester. Kovalente Fixierung erschwert Auswaschen, verhindert aber nicht photochemischen Abbau, Faserabbau oder andere chemische Veränderungen.','The ionic dye favors water and has no suitable polyester fixation route in this model. Covalent fixation impedes washing out but does not prevent photochemical degradation, fiber breakdown or other chemical changes.')]),'Eine begründete Stoffauswahl auf Basis von Wechselwirkungen. Keine praktische Färbeausführung wird aus dem Papiermodell abgeleitet.')

add(9,'experiment',[
('Küpenfärbung macht einen schwer löslichen oxidierten Farbstoff durch Reduktion löslich und oxidiert ihn nach Faseraufnahme wieder.','Vat dyeing reduces an insoluble oxidized dye to a soluble form and reoxidizes it after fiber uptake.','Erklärt Reihenfolge, Redoxwechsel und Löslichkeit ohne Stoffumwandlung zu verwechseln.','Explains sequence, redox change and solubility without conflating them.'),
('Kontrollen und Sauerstoffkontakt prüfen das Funktionsmodell.','Controls and oxygen exposure test the operating model.','Begründet einen Vergleich und trennt Beobachtung von Interpretation.','Justifies a comparison and separates observation from interpretation.'),
('Durchführung erfordert tatsächlich beobachtete sichere Handlungen und ein eigenes Rohprotokoll.','Execution requires actually observed safe actions and an original raw log.','Führt den freigegebenen Mikroversuch unter Aufsicht aus und dokumentiert reale Beobachtungen.','Carries out the approved microscale experiment under supervision and records real observations.')],[('Reduktion fehlt versus vollständige Küpe','No reduction versus a complete vat'),('Luftkontakt und Färbemethodenvergleich','Air exposure and dyeing-method comparison')],
case('Indigoküpe mit Kontrollstück','Indigo vat with a control swatch','Entwurf für einen späteren beaufsichtigten Mikroversuch, noch nicht ausgeführt. Lehrkraft stellt nach freigegebener Schul-SOP eine frisch reduzierte alkalische Indigoküpe, ein gleich konzentriertes nichtreduziertes Indigobad und zwei gleiche Baumwollstücke bereit. Keine Herstellung durch Lernende; Schutzbrille, Handschuhe, Pinzette und Abfallsammlung nach SOP. Sollfolge: 30 s eintauchen, entnehmen, 2 min Luftkontakt, nach SOP spülen. Protokollfelder bleiben leer: Badfarbe, Faserfarbe direkt/nach Luft, Spülwasserfarbe, Abweichung.','Design for a future supervised microscale experiment, not yet performed. The teacher supplies a freshly reduced alkaline indigo vat, an equally concentrated unreduced indigo bath and two identical cotton swatches under an approved school SOP. Learners do not prepare reagents; goggles, gloves, forceps and waste collection follow the SOP. Planned sequence: dip for 30 s, remove, expose to air for 2 min, rinse under SOP. Log fields are blank: bath color, fiber color immediately/after air, rinse-water color and deviations.',[
('Erkläre die Reduktion zur löslichen Leukoform, Faseraufnahme und Luftoxidation zurück zum schwer löslichen Indigo; schreibe die basische Halbreaktion I+2e⁻⇌L²⁻ mit den Rollen der Formen.','Explain reduction to soluble leuco form, fiber uptake and air oxidation back to poorly soluble indigo; write the basic half-reaction I+2e⁻⇌L²⁻ and identify the forms.'),
('Begründe die nichtreduzierte Kontrolle und benenne zwei konstant zu haltende Bedingungen sowie eine Auswertungsgrenze.','Justify the unreduced control and name two conditions to keep constant and one inference limit.'),
('Führe beide Färbungen unter Aufsicht mit der vorgegebenen SOP aus; lasse Eintauchen, Entnehmen, Luftkontakt und Spülen direkt beobachten und dokumentiere alle fünf Rohprotokollfelder für beide Stücke.','Carry out both dyeings under supervision using the supplied SOP; have dipping, removal, air exposure and rinsing directly observed and record all five raw-log fields for both swatches.')],[
('I ist neutrales oxidiertes Indigo; in stark alkalischer Küpe wird es zu L²⁻ reduziert, der besser wasserlöslichen dianionischen Leukoform. I+2e⁻⇌L²⁻ ist ladungsbilanziert. Nach Aufnahme in die Faser gibt L²⁻ bei Oxidation Elektronen ab; schwer lösliches I bleibt in der Faser. Die gelbliche/grünliche Küpenfarbe und spätere Blaufärbung sind Erwartungen, keine hier beobachteten Ergebnisse.','I is neutral oxidized indigo; a strongly alkaline vat reduces it to L²⁻, the more water-soluble dianionic leuco form. I+2e⁻⇌L²⁻ balances charge. After fiber uptake L²⁻ loses electrons upon oxidation; poorly soluble I remains in the fiber. Yellowish/greenish vat color and later blue are predictions, not observed results here.'),
('Die Kontrolle prüft den Beitrag der Reduktion zur Aufnahme. Beispielsweise Stückgröße und Tauchzeit müssen gleich sein. Unterschiede in Benetzung oder Küpenalter können die Interpretation begrenzen; dies ist kein quantitativer Vergleich der aufgenommenen Stoffmenge.','The control tests the role of reduction in uptake. For example, swatch size and dipping time must be equal. Wetting differences or vat age can limit interpretation; this is not a quantitative measurement of dye uptake.'),
('2 Punkte nur bei tatsächlich beobachteter vollständiger SOP-Handlung beider Stücke und eigenem vollständigem Rohlog; 1 für eine beobachtete Teilfolge mit zugehörigen Rohdaten; 0 ohne reale Beobachtung. Erwartungsfarben oder abgeschriebene Musterlogs sind kein Ausführungsnachweis. Der Autorversuch ist nicht durchgeführt.','2 points require actually observed complete SOP actions for both swatches and a complete original raw log; 1 for an observed partial sequence with its raw data; 0 without real observation. Predicted colors or copied model logs are not execution evidence. The author experiment has not occurred.')],practical=True),
case('Luftoxidation und Direktfärbung vergleichen','Comparing air oxidation and direct dyeing','Späterer Schulversuch unter freigegebener Mikro-SOP: Lehrkraft liefert reduzierte Indigoküpe und einen für Baumwolle geeigneten wässrigen Direktfarbstoff. Drei gleiche Stücke: A Indigo mit sofort 2 min Luftkontakt; B Indigo mit erster Beobachtung in der Küpe, dann 2 min Luftkontakt; C Direktfarbstoff gemäß Lehrer-SOP. Gleiche Endspülung. Lernende ändern weder Reagenzien noch Schutz-/Abfallregeln. Leere Felder für Aufnahmezustand, Farbverlauf, Spülwasser und Abweichung; keine synthetischen Messwerte.','Future school experiment under an approved microscale SOP: teacher supplies reduced indigo vat and an aqueous direct dye suitable for cotton. Three equal swatches: A indigo with immediate 2 min air exposure; B indigo first observed in the vat, then 2 min air exposure; C direct dye under teacher SOP. Same final rinse. Learners do not change reagents or protection/waste rules. Blank fields record uptake state, color sequence, rinse water and deviations; no synthetic measurements.',[
('Erkläre den erwarteten Farbverlauf bei A und B über Elektronenabgabe an Luftsauerstoff und den Wechsel der Löslichkeit; unterscheide erwartete von tatsächlich gemessenen Farben.','Explain the predicted color sequence in A and B through electron transfer to air oxygen and the solubility change; distinguish predictions from actually observed colors.'),
('Vergleiche Küpen- und Direktfärbung hinsichtlich löslicher Aufnahmeform und Fixierungsprinzip; begründe eine passende Kontrolle und eine Grenze der subjektiven Farbstärke.','Compare vat and direct dyeing in soluble uptake form and fixation principle; justify a suitable control and one limit of subjective color intensity.'),
('Führe die drei freigegebenen Abläufe unter direkter Lehrerbeobachtung aus und protokolliere Aufnahmezustand, Farbverlauf, Spülwasser und Abweichung für jedes Stück; kennzeichne nicht ausgeführte Schritte ausdrücklich.','Perform the three approved sequences under direct teacher observation and log uptake state, color sequence, rinse water and deviations for each swatch; explicitly mark any unperformed steps.')],[
('In der Küpe liegt die reduzierte lösliche Leukoform vor; nach Luftkontakt wird sie oxidiert und bildet schwer lösliches blaues Indigo. B macht den zeitlichen Wechsel nach der Erstbeobachtung zugänglich; A erhält sofort Luft. Das sind Modellvorhersagen, bis echte Rohbeobachtungen vorliegen.','The vat contains reduced soluble leuco form; air exposure oxidizes it to poorly soluble blue indigo. B makes the temporal change accessible after the initial observation; A receives air immediately. These remain model predictions until actual raw observations exist.'),
('Beide Methoden nehmen Farbstoff aus dem Bad auf. Die Küpe wechselt die Redox-/Löslichkeitsform und lagert schwer lösliches Indigo ein; der Direktfarbstoff bindet ohne diesen Redoxwechsel über geeignete intermolekulare Affinität. Ein ungefärbtes gleich behandeltes Stück kontrolliert Fasergrundfarbe. Subjektive Dunkelheit allein ist keine Konzentrationsmessung.','Both take up dye from a bath. The vat changes redox/solubility form and deposits poorly soluble indigo; the direct dye binds through suitable intermolecular affinity without that redox change. An undyed equally treated swatch controls background color. Subjective darkness alone does not measure concentration.'),
('Ausführungskriterium: direkte Beobachtung der tatsächlich freigegebenen Handlungen und vollständiger eigener Vier-Felder-Rohlog für A/B/C; Teilfolge erlaubt 1 Punkt, vollständig 2. Keine Punkte für nie ausgeführte Handlungen, erwartete Farben oder Musterprotokolle.','Execution criterion: direct observation of the approved actions actually performed and a complete original four-field log for A/B/C; a partial sequence earns 1 point, completion 2. Unperformed actions, predicted colors or model logs earn no execution credit.')],practical=True),'Ein zusammenhängender Küpenprozess mit realer Durchführung und optionalem ausdrücklich angefordertem Vergleich. Machine-QS beurteilt die Eignung des Designs, keine bereits erbrachte Klassenleistung. Landesquelle BY C13-EA.2.9 enthält den Ausführungsoperator eindeutig.')

add(10,'data',[
('Farbstoffproduktion kann Forschung, Skalierung und Absatz der chemischen Industrie verbinden.','Dye production can connect research, scale-up and markets in the chemical industry.','Leitet wirtschaftliche Wirkung aus benannten Daten und Mechanismen ab.','Infers economic impact from stated data and mechanisms.'),
('Eine historisch-wirtschaftliche Bewertung braucht Grenzen und Gegenargumente; Korrelation genügt nicht zur Alleinursache.','Historical economic judgment needs limits and counterarguments; correlation does not establish sole causation.','Gewichtet Nutzen und Kosten und begrenzt eine Kausalaussage.','Weighs benefits and costs and limits a causal claim.')],[('Skalierung und Marktpreise','Scale-up and prices'),('Forschungstransfer und Umweltkosten','Research transfer and environmental costs')],
case('Fabrik A wächst mit synthetischem Farbstoff','Factory A grows with a synthetic dye','Erfundenes historisches Modell, keine realen Firmendaten: vor Umstellung 200 Beschäftigte, 20 t Farbstoff/Jahr, Preis 12 Einheiten/kg; danach 600 Beschäftigte, 120 t/Jahr, Preis 5/kg. Forschungsabteilung wächst von 4 auf 30 Personen; Energiebedarf/Jahr steigt, Abwasserkosten fehlen. Gleichzeitig wird die Bahnverbindung verbessert.','Invented historical model, not real company data: before change, 200 employees, 20 t dye/year, price 12 units/kg; after, 600 employees, 120 t/year, price 5/kg. Research staff grows from 4 to 30; yearly energy demand rises and wastewater costs are missing. Railway access also improves.',[
('Beurteile anhand von Mengen-, Preis- und Forschungsdaten zwei Wege, wie die Farbstoffproduktion die Industrieentwicklung fördern könnte.','Use output, price and research data to assess two ways dye production could promote industrial development.'),
('Prüfe die Aussage „Der Farbstoff allein verursachte das gesamte Wachstum“; benenne eine alternative Erklärung und eine fehlende Kostengröße für die Gesamtbewertung.','Assess “The dye alone caused all growth”; name one alternative explanation and one missing cost variable for the overall judgment.')],[
('Größere Produktion bei niedrigerem Preis kann breitere Märkte bedienen und Skalierung fördern. Die vergrößerte Forschung kann neue Verfahren und weitere Produkte entwickeln. Der sechsfachen Menge steht nicht automatisch sechsfacher Gewinn gegenüber, weil der Preis sinkt und Kosten fehlen.','Higher output at lower price can reach wider markets and promote scale-up. Expanded research can develop processes and additional products. Sixfold output does not automatically mean sixfold profit because price falls and costs are missing.'),
('Die Gleichzeitigkeit beweist keine alleinige Ursache. Besserer Bahnanschluss könnte Absatz und Transportkosten beeinflussen. Abwasserbehandlungskosten oder zusätzliche Energiekosten fehlen; deshalb ist eine gesamte Rentabilitäts- oder Wohlfahrtsbilanz nicht bestimmt.','Coincidence does not prove a sole cause. Better rail access could affect sales and transport costs. Wastewater-treatment or added energy costs are missing, so total profitability or welfare is undetermined.')]),
case('Forschung nutzt Farbstoffwissen für neue Produkte','Research reuses dye knowledge for new products','Erfundenes Archivmodell: Firma B finanziert ein Analyselabor aus Farbstofferlösen. In zehn Jahren werden drei Verfahren zur organischen Synthese auf andere Produktgruppen übertragen. Marktanteil Farbstoffe sinkt von 70 auf 35 % des Umsatzes; Gesamtumsatz bleibt gleich. Eine Akte berichtet hohe Abwasserschäden, ohne Geldwert.','Invented archive model: company B funds an analytical laboratory from dye revenue. Over ten years, three organic synthesis methods transfer to other product groups. Dye share falls from 70 to 35% of revenue while total revenue stays constant. One file reports substantial wastewater harm without monetary valuation.',[
('Erkläre anhand der Akten einen plausiblen Beitrag der Farbstoffchemie zu Forschung und Produktdiversifizierung; deute den fallenden Umsatzanteil ohne ihn als Umsatzrückgang auszugeben.','Use the records to explain a plausible contribution of dye chemistry to research and product diversification; interpret the falling share without calling it a total-revenue decrease.'),
('Formuliere ein begründetes wirtschaftliches Urteil mit einem Nutzen, einer Belastung und einer Grenze der vorliegenden Daten.','Write a justified economic judgment with one benefit, one burden and one data limit.')],[
('Farbstofferlöse finanzieren Methodenwissen, das auf drei andere Verfahren übertragen wird. Bei konstantem Gesamtumsatz sinkt der Farbstoffumsatzanteil um 35 Prozentpunkte; andere Produktgruppen gewinnen Anteil. Dies passt zu Diversifizierung, belegt aber keinen Gesamtumsatzrückgang.','Dye revenue funds methods that transfer to three other processes. With constant total revenue the dye share falls by 35 percentage points while other groups gain share. This fits diversification but does not establish a total-revenue decrease.'),
('Die Farbstoffsparte wirkt als Finanzierungs- und Wissensquelle; gleichzeitig belasten Abwasserschäden die gesellschaftliche Bilanz. Ohne Schadenswert und Kosten kann ihr Nettobeitrag nicht exakt beziffert werden. Ein positives Innovationsurteil kann daher mit einer offenen Gesamtwohlfahrtsbilanz verbunden sein.','The dye division supplies funding and knowledge, while wastewater harm burdens the social balance. Without damage valuation and costs its net contribution cannot be quantified. A positive innovation judgment can coexist with an unresolved overall welfare balance.')]),'Ein kriteriengeleitetes wirtschaftshistorisches Urteil. Die Daten sind explizit erfunden, nicht als recherchierte reale Geschichte ausgegeben.')

add(11,'modeling',[
('Säure-Base- oder Redoxwechsel ändern Elektronenverteilung und Spektrum eines Indikators.','Acid-base or redox changes alter an indicator’s electron distribution and spectrum.','Verknüpft Teilchenform, Gleichgewicht und Farbe.','Connects particle form, equilibrium and color.'),
('Der Indikator zeigt ein chemisches Gleichgewicht, nicht einen beliebigen Farbumschlag ohne Strukturgrund.','An indicator reports a chemical equilibrium rather than an arbitrary color switch without structural basis.','Überträgt das Modell auf eine veränderte chemische Bedingung.','Transfers the model to a changed chemical condition.')],[('Protolyse versus Redoxform','Protolysis versus redox form'),('Gleichgewicht und Konjugationsunterbrechung','Equilibrium and interrupted conjugation')],
case('Protonierbarer Indikator','Protonatable indicator','Idealisierter Indikator HIn ⇌ H⁺ + In⁻: HIn hat im Modell unterbrochene ausgedehnte Konjugation und kein sichtbares Maximum; In⁻ ist planar konjugiert mit λmax 560 nm. pKₐ=7,0; gleicher solvent- und konzentrationsbezogener Zustand, keine weitere Protolyse.','Idealized indicator HIn ⇌ H⁺ + In⁻: HIn has interrupted extended conjugation and no visible maximum in this model; In⁻ is planar and conjugated with λmax 560 nm. pKₐ=7.0; same solvent and concentration conditions, no further protolysis.',[
('Erkläre den Zusammenhang zwischen den beiden Strukturformen und der sichtbaren Absorption; unterscheide das Gleichgewicht von mesomeren Grenzformeln.','Explain the connection between both structures and visible absorption; distinguish the equilibrium from resonance contributors.'),
('Bestimme mit [In⁻]/[HIn]=10^(pH−pKₐ) die dominierende Form bei pH 6 und 8 und erkläre die Farbumschlagrichtung.','Use [In⁻]/[HIn]=10^(pH−pKₐ) to identify the dominant form at pH 6 and 8 and explain the color-change direction.')],[
('In⁻ besitzt die längere konjugierte Elektronenverteilung und absorbiert im Modell sichtbar bei 560 nm; HIn nicht. HIn und In⁻ unterscheiden sich durch ein Proton und sind echte Teilchenformen im Gleichgewicht. Mesomere Formen desselben Teilchens unterscheiden sich nicht in Atomzusammensetzung.','In⁻ has the more extended conjugated distribution and absorbs visibly at 560 nm in the model; HIn does not. HIn and In⁻ differ by a proton and are real forms in equilibrium. Resonance contributors of one particle do not differ in composition.'),
('Bei pH 6 beträgt das Verhältnis 0,1: HIn dominiert. Bei pH 8 beträgt es 10: In⁻ dominiert. Steigender pH begünstigt die konjugierte sichtbare Absorberform, daher stärkere Indikatorfarbe; der Übergang ist graduell, kein scharfer Einzel-pH.','At pH 6 the ratio is 0.1, so HIn dominates. At pH 8 it is 10, so In⁻ dominates. Higher pH favors the conjugated visible absorber and therefore stronger indicator color; the transition is gradual, not one sharp pH value.')]),
case('Oxidiertes Blau und Leukoverbindung','Oxidized blue and leuco compound','Vereinfachtes Redoxindikator-Modell: B⁺ + H⁺ + 2e⁻ ⇌ BH. B⁺ ist delokalisiert, absorbiert im Modell 530–700 nm stark und lässt 430–480 nm weitgehend durch; BH hat ein unterbrochenes π-System und erscheint ohne weitere Banden farblos. Ein Reduktionsmittel liefert Elektronen; Luftsauerstoff kann den Rückweg fördern. Keine reale Stoffzubereitung.','Simplified redox-indicator model: B⁺ + H⁺ + 2e⁻ ⇌ BH. B⁺ is delocalized, strongly absorbs 530–700 nm in the model and largely transmits 430–480 nm; BH has an interrupted pi system and appears colorless without other bands. A reducing agent supplies electrons; air oxygen can promote reversal. No actual preparation.',[
('Prüfe die Ladungsbilanz und erkläre die Entfärbung bei Reduktion über die vorgegebene Strukturänderung; begründe die blaue Erscheinung der oxidierten Form.','Check charge balance and explain decolorization upon reduction through the supplied structural change; explain why the oxidized form looks blue.'),
('Erkläre die erwartete Rückfärbung bei Luftkontakt und begründe, warum dieses Signal allein keinen bestimmten pH-Wert misst.','Explain predicted recoloring on air exposure and why this signal alone does not measure a particular pH.')],[
('Links +1+1−2=0, rechts BH neutral. Reduktion unterbricht im Modell die ausgedehnte Delokalisierung, sodass die sichtbare Bande entfällt. B⁺ entzieht dem Weißlicht vorwiegend grüne bis rote Anteile; das verbleibende blaue Licht erklärt die modellierte blaue Erscheinung.','Left charge +1+1−2=0 equals neutral BH. Reduction interrupts extended delocalization in the model, removing the visible band. B⁺ removes mainly green-to-red components from white light; remaining blue light explains its modeled blue appearance.'),
('Luftsauerstoff wirkt als Elektronenakzeptor und ermöglicht Oxidation zurück zu B⁺. Das Signal hängt von Redoxbedingungen und gegebenenfalls auch Protonenaktivität ab; ohne Kalibrierung und definierte Bedingungen gibt es keinen eindeutigen pH-Wert.','Air oxygen acts as an electron acceptor and permits oxidation back to B⁺. The signal depends on redox conditions and potentially proton activity; without calibration and controlled conditions it gives no unique pH value.')]),'Ein Strukturänderungsmodell mit zwei zulässigen Reaktionsanlässen. Sek-I-Indikatorgebrauch belegt die vertiefte Elektronensystemerklärung nicht; diese Quellen-/Stufenzuordnungen bleiben offen.')

add(12,'procedure',[
('Halogenierung und Nitrierung am Benzol verlaufen über Elektrophilbildung, σ-Komplex und rearomatisierende Deprotonierung.','Benzene halogenation and nitration proceed via electrophile generation, sigma complex and rearomatizing deprotonation.','Stellt Elektronenpaarwege und Ladungsbilanz beider Beispiele dar.','Represents electron-pair movement and charge balance in both examples.'),
('Reaktionsbedingungen erzeugen unterschiedliche Elektrophile; Ring- und Seitenkettenreaktionen sind zu unterscheiden.','Conditions generate different electrophiles; ring and side-chain reactions must be distinguished.','Begründet Bedingungen und grenzt alternative Reaktionswege ab.','Justifies conditions and distinguishes alternative routes.')],[('Lewis-Säure-Halogenierung und Säure-Nitrierung','Lewis-acid halogenation and acid nitration'),('Ringreaktion versus radikalische Seitenkette','Ring reaction versus radical side chain')],
case('Bromierung und Nitrierung von Benzol','Bromination and nitration of benzene','Papierplanung, keine Ausführung. Modell Bromierung: Br₂/FeBr₃ ohne UV-Licht; Br₂ wird polarisiert, formale Br⁺/FeBr₄⁻-Schreibweise dient nur der Bilanz. Nitrierung: HNO₃/H₂SO₄ erzeugt NO₂⁺. Benzol ist krebserzeugend; alle Schritte bleiben Strukturanalyse.','Paper planning, no execution. Bromination model: Br₂/FeBr₃ without UV; Br₂ is polarized and formal Br⁺/FeBr₄⁻ notation is only bookkeeping. Nitration: HNO₃/H₂SO₄ generates NO₂⁺. Benzene is carcinogenic; all steps remain structural analysis.',[
('Stelle den Bromierungsmechanismus mit π-Paar→Br, Br–Br-Spaltung im Lewis-Säure-Komplex, positivem σ-Komplex und Deprotonierung durch FeBr₄⁻ dar; bilanziere Produkt und Katalysatorregeneration.','Show bromination with pi pair→Br, Br–Br cleavage in the Lewis-acid complex, positive sigma complex and deprotonation by FeBr₄⁻; balance product and catalyst regeneration.'),
('Formuliere die ladungsbilanzierte Nitroniumbildung und den Nitrierungsmechanismus mit Elektronenpaarpfeilen; begründe die Funktion der starken Säurebedingungen.','Write charge-balanced nitronium generation and nitration with electron-pair arrows; explain the role of strongly acidic conditions.')],[
('Ring-π greift das elektrophile Br im polarisierten Br₂·FeBr₃ an; Br–Br-Paar geht zum anderen Br im FeBr₄⁻-Rest. [C₆H₆Br]⁺ verliert am angegriffenen C H⁺; C–H-Paar→Ring-π. FeBr₄⁻ nimmt das Proton auf und liefert HBr+FeBr₃. Gesamt C₆H₆+Br₂→C₆H₅Br+HBr; FeBr₃ wird regeneriert. Freies Br⁺ in Lösung wird nicht behauptet.','Ring pi attacks electrophilic Br in polarized Br₂·FeBr₃; the Br–Br pair moves to the other Br in the FeBr₄⁻ residue. [C₆H₆Br]⁺ loses H⁺ at the attacked carbon; C–H pair→ring pi. FeBr₄⁻ accepts the proton, yielding HBr+FeBr₃. Overall C₆H₆+Br₂→C₆H₅Br+HBr; FeBr₃ is regenerated. Free Br⁺ in solution is not asserted.'),
('HNO₃+H₂SO₄⇌NO₂⁺+HSO₄⁻+H₂O (Gesamtladung 0). Ring-π→N von NO₂⁺; ein N=O-π-Paar→O verhindert N-Oktettüberschreitung. [C₆H₆NO₂]⁺ entsteht; Base entfernt Ring-H⁺, C–H-Paar→Ring-π. C₆H₆+HNO₃→C₆H₅NO₂+H₂O. H₂SO₄ protoniert HNO₃ und fördert Wasserabspaltung zur Elektrophilbildung.','HNO₃+H₂SO₄⇌NO₂⁺+HSO₄⁻+H₂O has net zero charge. Ring pi→N of NO₂⁺ while an N=O pi pair→O avoids exceeding nitrogen’s octet. [C₆H₆NO₂]⁺ forms; a base removes ring H⁺, C–H pair→ring pi. C₆H₆+HNO₃→C₆H₅NO₂+H₂O. H₂SO₄ protonates HNO₃ and promotes water loss to generate the electrophile.')]),
case('Ringbromierung oder Seitenkette?','Ring bromination or side chain?','Toluol-Papiervergleich: Route A Br₂/FeBr₃ ohne UV; Route B Br₂ mit Licht und radikalischer Initiierung. Eine dritte Ringreaktion ist Nitrierung mit HNO₃/H₂SO₄. Die Aufgaben vergleichen Mechanismen; Produktanteile sind nicht vorgegeben.','Toluene paper comparison: route A Br₂/FeBr₃ without UV; route B Br₂ with light and radical initiation. A third ring reaction is nitration with HNO₃/H₂SO₄. Mechanisms are compared; product proportions are not specified.',[
('Zeige für Route A die elektrophile Ringreaktion über σ-Komplex und Deprotonierung mit Elektronenpaarpfeilen; erkläre, warum Route B nicht derselbe Ringmechanismus ist.','Show route A’s electrophilic ring reaction through sigma complex and deprotonation using electron-pair arrows; explain why route B is not the same ring mechanism.'),
('Zeige den Nitrierungsmechanismus am Ring einschließlich NO₂⁺-Bildung und Ladungen; nenne je eine entscheidende Bedingung für Ringbromierung und Nitrierung.','Show ring nitration including NO₂⁺ generation and charges; name one decisive condition each for ring bromination and nitration.')],[
('A: Ring-π→polarisiertes Br, Br–Br-Spaltung zum FeBr₄⁻-Rest; Ring-σ-Komplex mit +1; FeBr₄⁻ entfernt H⁺, C–H-Paar rearomatisiert. B erzeugt Radikale und kann benzyliche H-Abstraktion/Substitution an der CH₃-Seitenkette bewirken; dies ist kein Arenium-Ionenmechanismus.','A: ring pi→polarized Br, Br–Br cleavage to the FeBr₄⁻ residue; ring sigma complex has +1; FeBr₄⁻ removes H⁺ and the C–H pair rearomatizes. B generates radicals and can cause benzylic H abstraction/substitution at the methyl side chain; it is not an arenium-ion mechanism.'),
('HNO₃+H₂SO₄⇌NO₂⁺+HSO₄⁻+H₂O. Ring-π→Nitronium-N, N=O-π→O; positiver σ-Komplex→H⁺-Abgabe mit C–H-Paar→Ring. Für A ist Lewis-Säure-Aktivierung des Br₂ entscheidend; für Nitrierung die starke Säure zur NO₂⁺-Bildung. Kein exakter Isomerenanteil folgt daraus.','HNO₃+H₂SO₄⇌NO₂⁺+HSO₄⁻+H₂O. Ring pi→nitronium N, N=O pi→O; positive sigma complex→H⁺ loss with C–H pair→ring. Lewis-acid activation of Br₂ is decisive for A; strong acid generating NO₂⁺ is decisive for nitration. Exact isomer proportions do not follow.')]),'Ein elektrophiler Substitutionsmechanismus mit zwei Elektrophilerzeugungen. Halogenierung/Nitrierung und Bedingungen sind ausdrücklich abgefragt; Forschungs-/Ausführungspunkte entstehen nicht.')

add(13,'representation',[
('Gültige Grenzformeln behalten Atome, σ-Gerüst, Elektronenzahl und Gesamtladung bei.','Valid resonance contributors preserve atoms, sigma framework, electron count and total charge.','Prüft und zeichnet chemisch zulässige Elektronenverteilungen.','Checks and draws chemically valid electron distributions.'),
('Energetisch günstige Grenzformeln haben angemessene Valenzen und geringe unnötige Ladungstrennung; der Hybrid ist kein einzelner Beitrag.','Energetically favorable contributors have valid valences and little unnecessary charge separation; the hybrid is not one contributor.','Bewertet Beiträge und begrenzt ihre Interpretation.','Evaluates contributors and limits their interpretation.')],[('Gültigkeit versus energetisches Gewicht','Validity versus energetic weight'),('Neutrale Form und Ladungstrennung','Neutral form and charge separation')],
case('Gültig, aber unterschiedlich gewichtet','Valid but differently weighted','Sechsring C1–C6, je ein H. A: C1=C2, C3=C4, C5=C6, sonst Einfachbindungen. B: C2=C3, C4=C5, C6=C1. C: C1⁺–C2⁻, C3=C4, C5=C6, sonst Einfachbindungen; C2 trägt ein freies Elektronenpaar. Alle σ-Bindungen bleiben gleich.','Six-membered C1–C6 ring, one H each. A: C1=C2, C3=C4, C5=C6, otherwise single bonds. B: C2=C3, C4=C5, C6=C1. C: C1⁺–C2⁻, C3=C4, C5=C6, otherwise single bonds; C2 has a lone pair. All sigma bonds remain unchanged.',[
('Prüfe für A, B und C Gesamtladung, Elektronenzahl und Valenzen; zeige den Elektronenpaarpfeil von A nach C.','Check net charge, electron count and valences in A, B and C; show the electron-pair arrow from A to C.'),
('Bewerte das relative energetische Gewicht von A/B gegenüber C und erkläre, warum die Grenzformeln keine getrennten Moleküle sind.','Assess relative energetic weight of A/B versus C and explain why contributors are not separate molecules.')],[
('A/B sind neutrale Kekulé-Beiträge mit sechs π-Elektronen und erfüllten C-Oktetten. C hat netto 0; das C1=C2-π-Paar liegt nun als freies Paar an C2, C1 besitzt ein Elektronensextett. Pfeil vom π-Paar C1=C2 zu C2, nicht Bewegung von H oder C.','A/B are neutral Kekulé contributors with six pi electrons and carbon octets. C has net zero charge; the C1=C2 pi pair is now a lone pair at C2 and C1 has an electron sextet. Arrow from the C1=C2 pi pair to C2, not movement of H or C.'),
('A und B sind gleichwertig und energetisch günstiger als C mit Ladungstrennung und C1-Oktettlücke. C ist ein zulässiger schwächerer Beitrag, kein zusätzliches Molekül im Gleichgewicht. Die reale Elektronendichte gehört zum Hybrid und ist nicht mit einer einzigen Formel identisch.','A and B are equivalent and energetically more favorable than C, which has charge separation and an octet deficiency at C1. C is a valid weaker contributor, not another equilibrium molecule. Real electron density belongs to the hybrid and is not identical to a single formula.')]),
case('Ein Wasserstoff wandert nicht in der Mesomerie','Hydrogen does not move in resonance','Benzol A besitzt C1=C2, C3=C4, C5=C6 und je ein H an C1–C6. Behaupteter Beitrag D verschiebt H von C1 nach C2, verändert damit zwei C–H-Bindungen und zeichnet eine andere Doppelbindungsverteilung. Beitrag E erhält alle H-Positionen und verschiebt nur die drei π-Paare zyklisch.','Benzene A has C1=C2, C3=C4, C5=C6 and one H on each C1–C6. Alleged contributor D moves H from C1 to C2, changing two C–H bonds and drawing another double-bond pattern. E retains all H positions and shifts only the three pi pairs cyclically.',[
('Entscheide, ob D und E Grenzformeln desselben Benzolmoleküls sein können; begründe mit Atomgerüst und Elektronenpaarbewegung.','Decide whether D and E can be contributors of the same benzene molecule; justify using the atomic framework and electron-pair movement.'),
('Zeichne den zulässigen zweiten neutralen Kekulé-Beitrag mit Elektronenpaarpfeilen und erkläre seine energetische Gleichwertigkeit sowie die Grenze der Zeichnung.','Draw the valid second neutral Kekulé contributor with electron-pair arrows and explain energetic equivalence and the limit of the drawing.')],[
('D ist keine Mesomerie, weil eine H-Atomposition und das σ-Gerüst geändert werden. E kann ein gültiger Beitrag sein: drei π-Paare verschieben sich ohne Änderung von Atomen, Gesamtladung oder σ-Bindungen.','D is not resonance because a hydrogen position and sigma framework change. E can be valid: three pi pairs shift without changing atoms, total charge or sigma bonds.'),
('Die zweite Formel hat C2=C3, C4=C5, C6=C1; drei gebogene Paarpfeile verbinden benachbarte π-Bindungspositionen. Beide neutralen Formeln sind bei Benzolsymmetrie gleichwertig. Die Zeichnung zeigt mögliche Elektronenbuchhaltung, keine laufende Bindungswanderung oder exakte Elektronendichte.','The second formula has C2=C3, C4=C5, C6=C1; three curved pair arrows connect adjacent pi-bond positions. Both neutral formulas are equivalent by benzene symmetry. The drawing shows electron bookkeeping, not moving bonds or an exact electron-density map.')]),'Eine zusammenhängende Darstellungsbewertung einschließlich energetischem Beitragsgewicht. Die Peptid-Mesomerie HH 1.3-025 ist kein Aromatenbeleg; kein Partnerkörper wird geändert.')

add(14,'modeling',[
('Acidität wird über Stabilisierung der konjugierten Base, Basizität über die Verfügbarkeit des protonenbindenden Elektronenpaars erklärt.','Acidity is explained through conjugate-base stabilization and basicity through availability of a proton-binding pair.','Verknüpft induktive und mesomere Effekte mit konkreten Teilchen.','Connects inductive and resonance effects to specific particles.'),
('Stellung, Protonierungsort und Lösungsmittel müssen beim Vergleich passen.','Position, protonation site and solvent must match in a comparison.','Begründet Reihenfolgen mit einem konsistenten Vergleich statt Ladungsheuristik.','Justifies rankings consistently rather than using a charge heuristic.')],[('Konjugierte Base und neutrales Basenpaar','Conjugate base and neutral base pair'),('Induktiver Abstand und Mesomeriekopplung','Inductive distance and resonance coupling')],
case('Phenol, Ethanol, Anilin, Cyclohexylamin','Phenol, ethanol, aniline, cyclohexylamine','Vergleich in Wasser, gleiche Temperatur. Gegebene näherungsweise pKₐ: Phenol 10, Ethanol 16; konjugierte Säure von Anilin 4,6, von Cyclohexylamin 10,6. Protonierungsort ist jeweils N; keine weiteren Substituenten.','Comparison in water at the same temperature. Approximate pKₐ values: phenol 10, ethanol 16; aniline’s conjugate acid 4.6 and cyclohexylamine’s 10.6. Protonation is at N; no other substituents.',[
('Vergleiche die Acidität von Phenol und Ethanol und erkläre den Unterschied mit den konjugierten Basen und mesomerer Stabilisierung.','Compare phenol and ethanol acidity and explain the difference using conjugate bases and resonance stabilization.'),
('Vergleiche die Basizität von Anilin und Cyclohexylamin anhand der angegebenen konjugierten Säuren; erkläre Elektronenpaar-Verfügbarkeit und induktiven Beitrag.','Compare aniline and cyclohexylamine basicity using the supplied conjugate-acid values; explain lone-pair availability and the inductive contribution.')],[
('Phenol ist bei kleinerem pKₐ saurer. Phenoxid kann Elektronendichte über O und den aromatischen Ring delokalisieren; Ethoxid hat keine entsprechende π-Kopplung. Die relativ stabilere konjugierte Base begünstigt die Protonenabgabe.','Phenol is more acidic at lower pKₐ. Phenoxide can delocalize electron density through O and the aromatic ring; ethoxide lacks corresponding pi coupling. The more stabilized conjugate base favors proton loss.'),
('Cyclohexylamin ist die stärkere Base: seine konjugierte Säure hat den höheren pKₐ. In Anilin ist das N-Paar in den Ring delokalisierbar und weniger für H⁺ verfügbar. Der Alkylrest am Cyclohexylamin liefert einen elektronenschiebenden induktiven Beitrag; die vorgegebenen Wasserwerte bestätigen den Gesamtvergleich.','Cyclohexylamine is the stronger base because its conjugate acid has higher pKₐ. Aniline’s N pair can delocalize into the ring and is less available to H⁺. The cyclohexyl alkyl group adds an electron-donating inductive contribution; the supplied water values confirm the overall comparison.')]),
case('Chlorabstand und Nitroanilin','Chlorine distance and nitroaniline','Gleiche wässrige Vergleichsbasis. Näherungsweise pKₐ: CH₃COOH 4,76; ClCH₂COOH 2,86; ClCH₂CH₂COOH 4,0. Anilin und para-Nitroanilin werden am Amino-N protoniert; die Nitrogruppe ist −I/−M.','Same aqueous comparison basis. Approximate pKₐ: CH₃COOH 4.76, ClCH₂COOH 2.86, ClCH₂CH₂COOH 4.0. Aniline and para-nitroaniline are protonated at amino N; nitro is −I/−M.',[
('Ordne die drei Säuren nach Stärke und erkläre, wie der Chlorabstand den induktiven Einfluss auf die konjugierte Base verändert.','Rank the three acids by strength and explain how chlorine distance changes its inductive effect on the conjugate base.'),
('Vergleiche die Aminobasizität von Anilin und para-Nitroanilin und erkläre dabei sowohl −I als auch die para-mesomere Kopplung.','Compare amino basicity of aniline and para-nitroaniline, explaining both −I and para resonance coupling.')],[
('ClCH₂COOH ist am stärksten, dann ClCH₂CH₂COOH, dann CH₃COOH. Cl zieht über σ-Bindungen Elektronendichte ab und stabilisiert die Carboxylatladung; der Effekt wird mit größerem Abstand schwächer.','ClCH₂COOH is strongest, followed by ClCH₂CH₂COOH and CH₃COOH. Chlorine withdraws density through sigma bonds and stabilizes carboxylate charge; the effect weakens with distance.'),
('para-Nitroanilin ist am Amino-N schwächer basisch. −I zieht Elektronendichte ab; der para-gekoppelte −M-Akzeptor fördert die Delokalisierung des Aminopaars durch den Ring. Das Paar ist weniger für Protonenbindung verfügbar.','para-Nitroaniline is less basic at amino N. −I withdraws electron density, while the para-coupled −M acceptor promotes delocalization of the amino pair through the ring. The pair is less available for proton bonding.')]),'Ein Struktur-Säure/Base-Vergleich; getrennte Aciditäts- und Basenbeispiele operationalisieren dasselbe I/M-Konzept. Authentischer BY bf96116a-Quelloperator recherchieren ist im aktuellen Körper nicht ausdrücklich enthalten; gesondert offen.')

add(15,'data',[
('Aromatische Struktur ist weder ein pauschaler Nutzennachweis noch ein einheitliches Gesundheitsrisiko.','An aromatic structure establishes neither uniform benefit nor uniform health risk.','Unterscheidet konkrete Stoffidentität, Verwendung und Gefährdungsbeleg.','Distinguishes chemical identity, use and hazard evidence.'),
('Risiko hängt von Expositionsweg, Dosis und Dauer ab und muss mit Nutzen und Alternativen abgewogen werden.','Risk depends on exposure route, dose and duration and must be weighed against benefit and alternatives.','Fällt ein kriteriengeleitetes bedingtes Urteil.','Makes a criteria-based conditional judgment.')],[('Rohstoff im geschlossenen Prozess versus offene Exposition','Closed-process feedstock versus open exposure'),('Gleicher Aromatenring, andere Stoffidentität','Same aromatic ring, different chemical identity')],
case('Benzol als Rohstoff oder offenes Lösemittel','Benzene as feedstock or open solvent','Primärbeleg: IARC Benzene, Vol.120 (2018), Evaluation 6.3: Benzol ist krebserzeugend für Menschen, Gruppe 1. Erfundener Entscheidungsfall: Verfahren A nutzt Benzol als Ausgangsstoff im geschlossenen System mit Rückgewinnung; B empfiehlt offene Reinigung am Arbeitsplatz; für B gibt es eine technisch geeignete benzolfreie Alternative. Expositionsmengen sind unbekannt.','Primary reference: IARC Benzene, Vol.120 (2018), Evaluation 6.3 classifies benzene as carcinogenic to humans, Group 1. Invented decision case: process A uses it as feedstock in a closed recovery system; B proposes open workplace cleaning; a technically suitable benzene-free alternative exists for B. Exposure amounts are unknown.',[
('Ordne die industrielle Funktion und den belegten Gesundheitsgefahrenstatus von Benzol ein; erkläre, warum Gruppe 1 keine konkrete Erkrankungswahrscheinlichkeit für A oder B angibt.','Identify benzene’s industrial role and documented health-hazard status; explain why Group 1 gives no specific disease probability for A or B.'),
('Bewerte beide Anwendungen nach Nutzen, Expositionsvermeidung und Alternativen; nenne eine fehlende Angabe, die ein abschließendes Betriebsurteil begrenzt.','Evaluate both uses using benefit, exposure prevention and alternatives; name one missing fact limiting a final operating judgment.')],[
('Benzol kann ein Synthese-Ausgangsstoff sein und ist laut IARC Gruppe 1 krebserzeugend. Die Gruppe bezeichnet die Stärke des Gefährdungsnachweises, keine Wahrscheinlichkeit für jede beliebige Dosis oder Arbeitsplatzsituation.','Benzene can serve as a synthesis feedstock and is carcinogenic in IARC Group 1. The group describes strength of hazard evidence, not probability at every dose or workplace situation.'),
('A hat einen Rohstoffnutzen und plausibel geringere Freisetzung durch Schließung, benötigt aber Nachweis wirksamer Kontrolle. Bei B spricht die geeignete Alternative und vermeidbare offene Exposition für Substitution. Tatsächliche Luftkonzentration, Dauer oder Leckagerate fehlen; Sicherheit oder Krankheitswahrscheinlichkeit kann nicht behauptet werden.','A has feedstock value and plausibly lower release through containment but needs evidence of effective control. For B, the suitable alternative and avoidable open exposure favor substitution. Actual air concentration, duration or leakage is unknown; neither safety nor disease probability can be claimed.')]),
case('Aromatenring ist kein Stoffurteil','An aromatic ring is not a chemical judgment','Erfundene Schulbroschüre: „Benzol ist krebserzeugend; deshalb ist jede aromatische Verbindung gleich gefährlich.“ Als Vergleich werden zwei fiktive nicht identische aromatische Stoffe R (Polymerrohstoff, flüchtig, inhalative Exposition möglich) und S (nicht flüchtiger fester Farbstoff, Staubexposition möglich) genannt. Für R/S liegen keine toxikologischen Daten vor.','Invented school brochure: “Benzene is carcinogenic, so every aromatic compound is equally hazardous.” Two fictitious different aromatic substances are compared: R, a volatile polymer feedstock with possible inhalation exposure, and S, a nonvolatile solid dye with possible dust exposure. No toxicological data are given for R/S.',[
('Prüfe die Broschürenaussage anhand Stoffidentität und Beweisgrenze; unterscheide die möglichen Expositionswege von R und S.','Assess the brochure claim using chemical identity and evidence limits; distinguish possible exposure routes for R and S.'),
('Formuliere eine bedingte Nutzungsbewertung mit je einem industriellen Nutzen und einer zu erhebenden Gesundheitsinformation; begründe, warum fehlende Daten nicht „harmlos“ bedeuten.','Write a conditional use judgment with one industrial benefit and one health information need for each; explain why missing data do not mean “harmless”.')],[
('Die Verallgemeinerung ist unzulässig: Benzoldaten sind keine toxikologischen Daten aller aromatischen Stoffe. R kann als Dampf, S trotz geringer Flüchtigkeit als Staub eingeatmet werden. Der Ring allein legt weder Gefahrstärke noch Expositionshöhe fest.','The generalization is invalid: benzene evidence is not toxicological evidence for all aromatics. R may be inhaled as vapor, and S as dust despite low volatility. The ring alone fixes neither hazard strength nor exposure level.'),
('R dient Polymerherstellung, S Färbung; Nutzen ist stoff- und prozessbezogen. Für beide werden konkrete toxikologische Daten und tatsächliche Exposition benötigt, bevor ein Gesundheitsurteil möglich ist. Ohne diese Daten bleibt die Bewertung offen; Unwissen ist kein Sicherheitsbeleg.','R supports polymer production and S coloration; benefits depend on substance and process. Specific toxicological data and actual exposure are required for both before a health judgment. Without them the judgment remains open; ignorance is not safety evidence.')]),'Ein Nutzen-/Risiko-Urteil zu identifizierten Stoffen; keine reale medizinische Risikoberechnung und kein Pauschalverbot durch Aromatizität.')

add(16,'modeling',[
('Absorption hebt Elektronen um eine erlaubte Energiedifferenz an; ΔE=hc/λ verbindet Übergang und Spektrum.','Absorption excites electrons across an allowed energy difference; ΔE=hc/λ connects transition and spectrum.','Zeichnet Energieniveaus und ordnet absorbierte Photonen zu.','Draws energy levels and assigns absorbed photons.'),
('Sichtbare Farbigkeit verlangt passende Absorption im sichtbaren Bereich und austretendes Restlicht.','Visible color requires suitable visible absorption and outgoing residual light.','Überträgt einen geänderten Energieabstand auf Farbe und Modellgrenze.','Transfers a changed energy gap to color and a model limit.')],[('Sichtbarer Übergang versus UV','Visible transition versus ultraviolet'),('Geänderte Konjugation und Energieabstand','Changed conjugation and energy gap')],
case('Zwei Übergangsabstände','Two transition gaps','Modellfarbstoff A hat einen erlaubten Übergang von 2,48 eV, B einen von 4,13 eV. hc=1240 eV·nm. Beide haben im Modell nur diese Bande; A ist nicht fluoreszierend. Sichtbarer Bereich hier 400–700 nm.','Model dye A has an allowed transition of 2.48 eV, B one of 4.13 eV. hc=1240 eV·nm. Each has only this band in the model; A is nonfluorescent. The visible range is 400–700 nm here.',[
('Zeichne für A und B ein Energienstufenschema mit aufwärts gerichtetem Absorptionspfeil und berechne jeweils die absorbierte Wellenlänge.','Draw energy-level schemes for A and B with upward absorption arrows and calculate each absorbed wavelength.'),
('Begründe, welches System durch diese Bande unter Weißlicht sichtbar farbig sein kann; erkläre, warum die absorbierte Wellenlänge nicht direkt seine Durchsichtfarbe ist.','Explain which system can be visibly colored by this band under white light; explain why the absorbed wavelength is not its transmitted color.')],[
('Je zwei Niveaus mit Abstand ΔE und Pfeil vom unteren zum oberen. A: 1240/2,48=500 nm; B: 1240/4,13≈300 nm. Der Pfeil beschreibt Energieaufnahme des delokalisierten Elektronensystems.','Each diagram has two levels separated by ΔE and an arrow from lower to upper. A: 1240/2.48=500 nm; B: 1240/4.13≈300 nm. The arrow represents energy uptake by the delocalized electron system.'),
('A absorbiert sichtbar, B nach dem Modell nur UV. A kann durch Entzug von 500-nm-Licht farbig erscheinen; die Farbe stammt aus dem übrigen durchgelassenen Spektrum, nicht aus dem absorbierten Photon. Ohne weitere sichtbare Banden ist B durchsichtig farblos.','A absorbs visibly; B absorbs only ultraviolet in the model. A can appear colored by removing 500 nm light; color comes from the remaining transmitted spectrum, not the absorbed photon. Without other visible bands B is colorless in transmission.')]),
case('Konjugation verändert den erlaubten Übergang','Conjugation changes the allowed transition','Zwei idealisierte Farbstoffformen mit gleicher Konzentration: lange planare Konjugation ΔE=2,00 eV; nach sp³-Unterbrechung ΔE=3,10 eV. hc=1240 eV·nm. Nur die angegebene Bande wird betrachtet; reale Moleküle besitzen weitere Übergänge.','Two idealized dye forms at equal concentration: long planar conjugation ΔE=2.00 eV; after sp³ interruption ΔE=3.10 eV. hc=1240 eV·nm. Only the stated band is considered; real molecules have additional transitions.',[
('Stelle beide Energieabstände dar, berechne die Wellenlängen und ordne die Richtung der Spektralverschiebung zu.','Represent both energy gaps, calculate wavelengths and identify the direction of spectral shift.'),
('Erkläre die Beziehung zwischen unterbrochener Delokalisierung und den gegebenen Energieabständen; nenne eine Grenze der Vorhersage der tatsächlichen Farbe aus einem einzigen Übergang.','Explain the relation between interrupted delocalization and the supplied energy gaps; state one limit of predicting actual color from a single transition.')],[
('2,00 eV→620 nm, 3,10 eV→400 nm. Der größere Abstand benötigt ein energiereicheres Photon und verschiebt die Bande zu kürzeren Wellenlängen, also hypsochrom. Beide Schemata haben aufwärts gerichtete Absorptionspfeile.','2.00 eV→620 nm and 3.10 eV→400 nm. The larger gap requires a higher-energy photon and shifts the band to shorter wavelengths, a hypsochromic shift. Both schemes have upward absorption arrows.'),
('Im angegebenen Vergleich erhöht die sp³-Unterbrechung den erlaubten Übergangsabstand gegenüber der langen Konjugation. Die tatsächliche Farbe hängt auch von Bandenbreite, weiteren Übergängen und Beleuchtung ab; ein ΔE-Wert liefert allein keine exakte Farbe.','In the supplied comparison sp³ interruption increases the allowed transition gap relative to long conjugation. Actual color also depends on bandwidth, other transitions and illumination; one ΔE alone does not determine an exact color.')]),'Ein Energie-Farb-Modell, nicht reine Formelsubstitution; Abgrenzung zu Emission/Reflexion und Spektrenauswertung bleibt sichtbar.')

add(17,'data',[
('Recherche muss Quelle, Stoffidentität, Nutzung und Gesundheitsbehauptung nachvollziehbar verbinden.','Research must traceably connect source, chemical identity, use and health claim.','Entnimmt Primärinformationen und belegt Fundstelle statt Werbeaussagen zu übernehmen.','Extracts primary information with a locator rather than adopting advertising.'),
('Gesundheitsbewertung unterscheidet Gefährdung von Exposition und vergleicht gleichartige Anwendungen.','Health judgment distinguishes hazard from exposure and compares like applications.','Gewichtet Nutzen, Exposition und Evidenzgrenzen.','Weighs benefit, exposure and evidence limits.')],[('Lebensmittelfarbe versus Textilfarbstoff','Food color versus textile dye'),('Primärquelle versus allgemeine Werbeaussage','Primary source versus a general advertisement')],
case('Farbstoffwahl für ein Getränk','Choosing a beverage color','Für eine Recherche liegt die Primärseite EFSA „Food colours“ (https://www.efsa.europa.eu/en/topics/topic/food-colours; geprüft 13.10.2026) bereit: Funktionen sind Farberhalt/-verstärkung, Sicherheitsbewertung ist stoffbezogen. Erfundenes Angebot: Lebensmittel-Farbe F mit exakter Identität und dokumentierter Bewertung; technischer Textilfarbstoff T ohne Lebensmitteldossier. Keine konkreten Zulassungs- oder Dosierungswerte werden geliefert.','For research the primary EFSA “Food colours” page is available (https://www.efsa.europa.eu/en/topics/topic/food-colours; checked 13 October 2026): functions include maintaining/enhancing color and safety assessment is substance-specific. Invented offer: food color F with exact identity and documented assessment; technical textile dye T without a food dossier. No specific authorization or dosage values are supplied.',[
('Recherchiere auf der angegebenen Primärseite je einen Nutzen und eine Aussage zur Sicherheitsprüfung; dokumentiere URL, Abschnitt und Abrufdatum und unterscheide Befund von der Werbeaussage „jede natürliche Farbe ist gesund“.','Research one benefit and one safety-assessment statement on the specified primary page; record URL, section and access date and distinguish evidence from the advertisement “every natural color is healthy”.'),
('Vergleiche F und T für die gleiche Getränkenutzung nach Stoffidentität, Expositionsweg und verfügbarer Gesundheitsprüfung; formuliere ein bedingtes Urteil und eine fehlende Information.','Compare F and T for the same beverage use by identity, exposure route and available health assessment; give a conditional judgment and one missing fact.')],[
('Nachprüfbarer Recherchebeleg: EFSA-URL, Abschnitt Einleitung/Sicherheitsbewertung und tatsächliches Abrufdatum; Farberhalt oder Farbverstärkung als Nutzen, stoffbezogene Bewertung als Sicherheitsbefund. Die Seite trägt keine pauschale Gesundheitsgarantie allein aufgrund natürlicher Herkunft. Bei nicht erfolgtem Abruf bleiben Recherchepunkte offen.','Verifiable research evidence names the EFSA URL, introduction/safety-assessment section and actual access date; color maintenance or enhancement is a benefit and substance-specific assessment is the safety finding. The page does not support a blanket health guarantee based on natural origin. Without an actual lookup, research credit remains unavailable.'),
('Bei Getränken ist orale Aufnahme der gemeinsame Vergleichsweg. F hat ein zur Verwendung passendes Dossier; T besitzt hier keines und ist daher keine belegte Lebensmittelalternative. Eine endgültige Entscheidung benötigt genaue Identität, Verwendungsbedingungen und Exposition/Dosierung; weder F noch T wird aus dem Modell als pauschal sicher oder toxisch erklärt.','In beverages oral intake is the common comparison route. F has a dossier matching its use; T has none here and is not an evidenced food alternative. A final decision needs exact identity, use conditions and exposure/dose; the model labels neither substance universally safe or toxic.')]),
case('Naturfarbstoff oder synthetische Farbe im Textil','Natural or synthetic textile color','Recherchequellen: EFSA „Food additives“ (https://www.efsa.europa.eu/en/topics/topic/food-additives) erläutert unterschiedliche Herkunft; die Primärseite „Food colours“ beschreibt stoffbezogene Prüfung. Erfundenes Textilangebot N nennt nur „pflanzlich“ ohne genaue Stoffidentität; S nennt eine genaue synthetische Identität, aber das Dossier betrifft orale Aufnahme, nicht Hautkontakt. Beide haben gleiche angenommene Farbechtheit.','Research sources: EFSA “Food additives” (https://www.efsa.europa.eu/en/topics/topic/food-additives) discusses different origins; “Food colours” describes substance-specific assessment. Invented textile offer N says only “plant-based” without exact identity; S names an exact synthetic identity but its dossier addresses oral intake rather than skin contact. Both have equal assumed color fastness.',[
('Recherchiere je einen Primärbefund zu Herkunft und stoffbezogener Prüfung und dokumentiere URL, Abschnitt, Abrufdatum; erkläre die Grenze der Übertragung von Lebensmitteldaten auf Textilien.','Research one primary finding each on origin and substance-specific assessment and record URL, section and access date; explain the limit of transferring food evidence to textiles.'),
('Vergleiche die Gesundheitsbelege von N und S für Hautkontakt und entscheide begründet, ob das Material eine Rangfolge „natürlich ist gesünder“ trägt; fordere eine konkret fehlende Information je Angebot.','Compare N and S health evidence for skin contact and assess whether the material supports “natural is healthier”; request one specific missing fact for each offer.')],[
('Ein tatsächlicher Recherchebeleg benennt beide EFSA-URLs, passende Abschnitte und Abrufdatum. Herkunft kann verschieden sein; Prüfung betrifft konkrete Stoffe und Expositionsbedingungen. Lebensmitteldaten beantworten nicht automatisch Hautkontakt oder Freisetzung aus einer Faser. Ohne Abruf kein Nachweis des Rechercheoperators.','Actual research evidence names both EFSA URLs, relevant sections and access date. Origins vary; assessment concerns particular substances and exposures. Food data do not automatically answer skin contact or release from a fiber. Without a lookup the research operator is not demonstrated.'),
('Die Daten tragen keine Gesundheitsrangfolge nach Herkunft. N benötigt Stoffidentität/Verunreinigungsprofil, S benötigt hautkontaktbezogene Bewertung oder Freisetzungsdaten. Gleiche angenommene Farbechtheit ersetzt keine toxikologische Evidenz; beide Angebote bleiben bis zu passenden Daten offen.','The data do not support a health ranking by origin. N needs identity/impurity information; S needs a skin-contact assessment or release data. Equal assumed fastness does not replace toxicological evidence; both remain unresolved pending matching data.')]),'Recherche und Vergleich dienen einem einzigen kriteriengeleiteten Farbstoffurteil; Recherche verlangt tatsächlichen nachvollziehbaren Quellenzugriff, keine fiktive Ausführung. Grundniveau BY3407 enthält Einsatzbewertung, EA d7b37 erweitert ausdrücklich Gesundheit.')

add(18,'modeling',[
('Dirigierung und Aktivierung sind verschiedene Folgen von I-, M- und Hyperkonjugationseffekten.','Orientation and activation are different consequences of inductive, resonance and hyperconjugative effects.','Begründet ortho/para oder meta über σ-Komplex-Stabilisierung.','Justifies ortho/para or meta orientation using sigma-complex stabilization.'),
('Protonierung verändert die elektronischen Eigenschaften eines Substituenten.','Protonation changes a substituent’s electronic properties.','Überträgt eine Richtungsregel auf die tatsächlich vorliegende Teilchenform.','Transfers orientation reasoning to the particle actually present.')],[('Toluol, Phenol, Anilin und Nitrobenzol','Toluene, phenol, aniline and nitrobenzene'),('Neutrales Anilin versus Anilinium','Neutral aniline versus anilinium')],
case('Vier Substituenten im gleichen Papiermodell','Four substituents in one paper model','Elektrophile Ring-Zweitsubstitution an Toluol, Phenol, neutralem Anilin und Nitrobenzol. Protonierung und Nebenreaktionen sind im ersten Vergleich ausgeschlossen; exakte Produktanteile werden nicht gefragt.','Electrophilic ring secondary substitution on toluene, phenol, neutral aniline and nitrobenzene. Protonation and side reactions are excluded for the first comparison; exact product proportions are not requested.',[
('Ordne für alle vier Stoffe bevorzugte Zweitsubstitutionsrichtung und Aktivierung/Desaktivierung relativ zu Benzol zu; begründe mit I/M-Effekt oder Hyperkonjugation.','Assign preferred orientation and activation/deactivation relative to benzene for all four compounds; justify using I/M effects or hyperconjugation.'),
('Erkläre am σ-Komplex, warum –NH₂ ortho/para begünstigt und –NO₂ meta begünstigt; unterscheide Richtungspräferenz von garantierter Produktreinheit.','Use sigma complexes to explain why –NH₂ favors ortho/para and –NO₂ favors meta; distinguish orientation preference from guaranteed pure product.')],[
('Toluol: ortho/para, aktiviert durch +I/Hyperkonjugation. Phenol und neutrales Anilin: ortho/para, aktiviert durch +M der freien Paare, trotz −I. Nitrobenzol: meta und desaktiviert durch −I/−M.','Toluene: ortho/para and activated through +I/hyperconjugation. Phenol and neutral aniline: ortho/para and activated through lone-pair +M despite −I. Nitrobenzene: meta and deactivated through −I/−M.'),
('Bei ortho/para-Angriff am Anilin kann das N-Paar eine zusätzliche σ-Komplex-Grenzformel mit N⁺ stabilisieren. Bei Nitrobenzol enthalten ortho/para-Komplexe besonders ungünstige Beiträge mit positiver Ringladung am nitrotragenden C; meta vermeidet diese zusätzliche Destabilisierung. Präferenz bedeutet Gemische, keine alleinige Isomerenbildung.','For ortho/para attack on aniline the N pair adds a stabilizing sigma-complex contributor bearing N⁺. Nitrobenzene ortho/para complexes contain especially unfavorable contributors with positive ring charge at the nitro-bearing carbon; meta avoids that extra destabilization. Preference permits mixtures, not exclusive isomer formation.')]),
case('Anilin in stark saurer Umgebung','Aniline in strongly acidic surroundings','Zwei gedachte Bedingungen: A enthält überwiegend neutrales Anilin; B überwiegend C₆H₅–NH₃⁺. Toluol und Phenol bleiben im Vergleich neutral. Keine tatsächliche Nitrierung wird durchgeführt; keine Produktquoten.','Two hypothetical conditions: A contains mainly neutral aniline; B mainly C₆H₅–NH₃⁺. Toluene and phenol remain neutral in the comparison. No actual nitration or product quotas.',[
('Vergleiche Anilin und Anilinium hinsichtlich freiem Elektronenpaar, mesomerem Beitrag und bevorzugter Zweitsubstitutionsrichtung.','Compare aniline and anilinium in lone-pair availability, resonance contribution and preferred secondary-substitution orientation.'),
('Begründe die weiterhin ortho/para-begünstigende Wirkung von neutralem Toluol und Phenol; erkläre, warum eine Aussage über Anilin stets die Protonierungsbedingungen nennen muss.','Justify continuing ortho/para preference for neutral toluene and phenol; explain why aniline predictions must specify protonation conditions.')],[
('Anilin hat ein freies N-Paar und +M: ortho/para und aktiviert. Anilinium hat vier N-Bindungen, kein freies Paar für +M und starken −I-Effekt: desaktiviert und meta-dirigierend im idealisierten elektrophilen Modell.','Aniline has a free N pair and +M: ortho/para and activated. Anilinium has four N bonds, no free pair for +M and strong −I: deactivated and meta-directing in the idealized electrophilic model.'),
('Toluol stabilisiert geeignete σ-Komplexe durch Hyperkonjugation/+I; Phenol durch +M des O-Paars. Bei Anilin entscheidet die tatsächliche Protonierungsform darüber, ob der N-Donoreffekt verfügbar ist. Eine neutrale Strukturregel ist in stark saurer Lösung daher nicht ungeprüft übertragbar.','Toluene stabilizes suitable sigma complexes through hyperconjugation/+I; phenol through O-pair +M. In aniline the actual protonation state determines whether N donation is available. A neutral-structure rule cannot therefore be transferred unchecked to strongly acidic solution.')]),'Ein Zweitsubstitutionsmodell über vier ausdrücklich genannte Beispiele und Bedingungen. Aktueller EN-Körper lässt Anilin/Nitrobenzol aus: begrenzter Übersetzungsvorschlag; ursprüngliche Bindung bleibt erhalten.')

add(19,'procedure',[
('Ein σ-Komplex besitzt eine neue C–E-σ-Bindung, ein sp³-Ringzentrum und delokalisierte positive Ladung, aber keine vollständige Aromatizität.','A sigma complex has a new C–E sigma bond, an sp³ ring center and delocalized positive charge, but not full aromaticity.','Stellt Zwischenstufe und Elektronenpaarfluss korrekt dar.','Represents the intermediate and electron-pair movement correctly.'),
('Deprotonierung stellt das zyklische π-System wieder her und ergibt Substitution statt Addition.','Deprotonation restores the cyclic pi system and gives substitution rather than addition.','Verknüpft Protonenabgabe, Elektronenpaar und Produkt.','Connects proton loss, electron pair and product.')],[('Allgemeines E⁺ und konkretes NO₂⁺','General E⁺ and specific NO₂⁺'),('Protonenabgabe versus fälschlicher H⁻-Abgang','Proton loss versus erroneous hydride departure')],
case('Allgemeiner elektrophiler Angriff','General electrophilic attack','Benzolring C1–C6 mit einem H je C. E⁺ greift am C1 an; Base B ist neutral. E ist ein einwertig gebundener Rest; Gegenionen sind ausgeblendet.','Benzene ring C1–C6 has one H on each C. E⁺ attacks at C1; base B is neutral. E is a singly bonded residue; counterions are omitted.',[
('Zeige den Elektronenpaarpfeil des Ringangriffs und zeichne den σ-Komplex mit E und H an C1, Gesamtladung und drei Ladungs-Grenzformen.','Show the ring-attack electron-pair arrow and draw the sigma complex with E and H at C1, net charge and three charge contributors.'),
('Zeige die Deprotonierung mit Paarpfeilen zu B und zurück in den Ring, bilanziere C₆H₆+E⁺+B→C₆H₅E+BH⁺ und erkläre die Wiederherstellung der Aromatizität.','Show deprotonation with pair arrows involving B and back into the ring, balance C₆H₆+E⁺+B→C₆H₅E+BH⁺ and explain restored aromaticity.')],[
('Ein Ring-π-Paar bindet E an C1. C1 trägt danach zwei Ring-σ-Bindungen, H und E und ist sp³. Der σ-Komplex hat +1; die positive Ladung kann bei festem C1-Gerüst in Grenzformeln an C2, C4 oder C6 liegen. Das verbliebene π-Segment ist delokalisiert, der vollständige π-Ring jedoch unterbrochen.','A ring pi pair binds E to C1. C1 then has two ring sigma bonds, H and E and is sp³. The sigma complex has +1; at fixed C1 framework the positive charge can appear at C2, C4 or C6. The remaining pi segment is delocalized, but the full pi ring is interrupted.'),
('B-Paar→H an C1; C1–H-Paar→passende benachbarte Ringbindung. C1 wird sp² und der sechsgliedrige π-Ring kehrt zurück. Atome und Ladung (+1 links/rechts) sind bilanziert; E ersetzt H, also Substitution.','B lone pair→H on C1; C1–H pair→the appropriate adjacent ring bond. C1 becomes sp² and the six-membered pi ring returns. Atoms and charge (+1 on both sides) balance; E replaces H, giving substitution.')]),
case('Fehlerhafte Nitrierungszeichnung reparieren','Repairing an incorrect nitration drawing','Eine Papierzeichnung zeigt: Benzol + NO₂⁺ bildet einen „weiter aromatischen σ-Komplex“; anschließend verlässt H⁻ den Ring. Die korrigierende Base ist HSO₄⁻. Nur die Ringstufen, nicht Nitroniumbildung, werden geprüft.','A paper drawing shows benzene + NO₂⁺ forming a “still aromatic sigma complex”, then H⁻ leaving the ring. The correcting base is HSO₄⁻. Only ring steps, not nitronium generation, are assessed.',[
('Korrigiere Ringangriff und σ-Komplex mit Elektronenpaarpfeilen, Nitrogen-Oktett, sp³-Zentrum und Gesamtladung.','Correct ring attack and sigma complex using electron-pair arrows, nitrogen octet, sp³ center and net charge.'),
('Korrigiere den Abgang als Protonenübertragung an HSO₄⁻ mit Rückführung des C–H-Paars in den Ring; schreibe die ladungsbilanzierte Ring-Gesamtgleichung.','Correct departure as proton transfer to HSO₄⁻ with the C–H pair returning to the ring; write a charge-balanced overall ring equation.')],[
('Ring-π→N von NO₂⁺, N=O-π→O; der Nitrorest besitzt N⁺/O⁻ in der üblichen Lewisform. Die zusätzliche σ-Komplex-Gesamtladung +1 liegt im Ring; das angegriffene C trägt H und NO₂ und ist sp³. Der vollständige π-Ring ist unterbrochen und nicht aromatisch.','Ring pi→N of NO₂⁺ and N=O pi→O; the nitro group has N⁺/O⁻ in the usual Lewis representation. The additional sigma-complex net +1 lies in the ring; the attacked carbon bears H and NO₂ and is sp³. The full pi ring is interrupted and nonaromatic.'),
('HSO₄⁻-O-Paar→H; C–H-Paar→Ringbindung. H⁺, nicht H⁻, wird übertragen, sodass die Elektronen im Ring bleiben. C₆H₆+NO₂⁺+HSO₄⁻→C₆H₅NO₂+H₂SO₄: links und rechts Ladung 0.','HSO₄⁻ oxygen pair→H; C–H pair→ring bond. H⁺ rather than H⁻ transfers, leaving the electrons in the ring. C₆H₆+NO₂⁺+HSO₄⁻→C₆H₅NO₂+H₂SO₄ has zero charge on both sides.')]),'Ein allgemeiner σ-Komplex-Mechanismus; Fehlerdiagnose verlangt keinen vollständigen unabhängigen Halogenierungs-/Nitrierungsbedingungskatalog.')

add(20,'procedure',[
('Friedel-Crafts-Alkylierung und -Acylierung erzeugen unterschiedliche Elektrophile und besitzen unterschiedliche Umlagerungs-/Mehrfachreaktionsrisiken.','Friedel-Crafts alkylation and acylation generate different electrophiles and have different rearrangement/multiple-reaction risks.','Plant den passenden Reaktionstyp und begründet seine Grenzen.','Plans an appropriate reaction type and justifies its limits.'),
('Substrataktivierung, Lewis-Säure-Komplexierung und Nachbehandlung bestimmen die Steuerbarkeit.','Substrate activation, Lewis-acid complexation and workup determine controllability.','Überträgt die Planung auf ein chemisch verändertes Substrat.','Transfers planning to a chemically changed substrate.')],[('Direktalkylierung versus Acylierung/Reduktion','Direct alkylation versus acylation/reduction'),('Aktivierter Ring versus Nitrobenzol','Activated ring versus nitrobenzene')],
case('n-Propylbenzol gezielt planen','Planning n-propylbenzene selectively','Papier-Syntheseplanung; keine Ausführung. Ziel Ph–CH₂CH₂CH₃ aus Benzol. Optionen: A 1-Chlorpropan/AlCl₃; B Propanoylchlorid CH₃CH₂COCl/AlCl₃ mit anschließender geeigneter Carbonylreduktion zum CH₂. Im Modell kann primäres Alkyl-Elektrophil zu sekundärem umlagern; Arylketone deaktivieren den Ring.','Paper synthesis planning; no execution. Target Ph–CH₂CH₂CH₃ from benzene. Options: A 1-chloropropane/AlCl₃; B propanoyl chloride CH₃CH₂COCl/AlCl₃ followed by suitable carbonyl reduction to CH₂. In the model a primary alkyl electrophile can rearrange to secondary; aryl ketones deactivate the ring.',[
('Vergleiche beide Routen hinsichtlich Kohlenstoffgerüst und Umlagerung; plane die passende Route mit Zwischenprodukt und Elektronenpaarwegen der elektrophilen Ringstufe.','Compare both routes in carbon framework and rearrangement; plan the suitable route with intermediate product and electron-pair movement in the electrophilic ring step.'),
('Erkläre die Gefahr der Mehrfachalkylierung in A sowie die geringere Zweitacylierung in B; begründe Lewis-Säure-Bedarf und die Rolle der Nachbehandlung.','Explain multiple-alkylation risk in A and reduced second acylation in B; justify Lewis-acid demand and the role of workup.')],[
('B ist kontrollierbarer: CH₃CH₂CO⁺ (Acylium, R–C≡O⁺↔R–C⁺=O) wird ohne Alkylumlagerung am Ring angegriffen; Ring-π→Acyl-C, ein C≡O-π-Paar→O, positiver σ-Komplex, dann Protonenabgabe. Ph–COCH₂CH₃ wird anschließend zu Ph–CH₂CH₂CH₃ reduziert. A kann durch Umlagerung Isopropylbenzol ergeben.','B is more controllable: CH₃CH₂CO⁺ (acylium, R–C≡O⁺↔R–C⁺=O) undergoes ring attack without alkyl rearrangement; ring pi→acyl C, one C≡O pi pair→O, positive sigma complex, then proton loss. Ph–COCH₂CH₃ is subsequently reduced to Ph–CH₂CH₂CH₃. A may rearrange to give isopropylbenzene.'),
('Ein Alkylrest aktiviert den Ring, sodass weitere Alkylierung möglich ist. Der Acylrest desaktiviert und vermindert weitere elektrophile Substitution. AlCl₃ aktiviert das Chlorid und komplexiert das Ketonprodukt; deshalb ist Acylierung nicht pauschal nur katalytisch im AlCl₃-Bedarf. Die Nachbehandlung löst den Produktkomplex; Reduktion ist ein getrennter Schritt.','An alkyl group activates the ring, allowing further alkylation. An acyl group deactivates and reduces further electrophilic substitution. AlCl₃ activates the chloride and complexes the ketone product, so acylation must not be assumed universally catalytic in AlCl₃ demand. Workup releases the product complex; reduction is a separate step.')]),
case('Anisol oder Nitrobenzol acylieren','Acylating anisole or nitrobenzene','Papiervergleich: Anisol und Nitrobenzol sollen mit CH₃COCl/AlCl₃ zu Ring-Acetylprodukten umgesetzt werden. Anisol ist ortho/para-aktiviert; Nitrobenzol ist stark desaktiviert. Lewis-Säure-Komplexierung kann die Selektivität beeinflussen; konkrete Ausbeuten sind nicht gegeben.','Paper comparison: anisole and nitrobenzene are proposed for ring acetylation with CH₃COCl/AlCl₃. Anisole is ortho/para-activated; nitrobenzene is strongly deactivated. Lewis-acid complexation can affect selectivity; actual yields are not given.',[
('Entscheide, welches Substrat eine plausible klassische Friedel-Crafts-Acylierung erlaubt; plane Elektrophilbildung, σ-Komplex und Rearomatisierung sowie plausible Positionsisomere.','Decide which substrate permits plausible classical Friedel-Crafts acylation; plan electrophile generation, sigma complex and rearomatization with plausible positional isomers.'),
('Begründe das Hindernis bei Nitrobenzol und erläutere, wie Acylierung gegenüber Alkylierung Umlagerung und Mehrfachsubstitution begrenzt; nenne eine Grenze exakter Selektivitätsplanung.','Explain the obstacle for nitrobenzene and how acylation limits rearrangement and multiple substitution compared with alkylation; state one limit to exact selectivity planning.')],[
('Anisol ist der plausible Kandidat. CH₃COCl+AlCl₃ liefert formal CH₃CO⁺+AlCl₄⁻; Ring-π greift Acyl-C an, bei Dreifachbindungsdarstellung geht ein C≡O-Paar zu O. Positiver σ-Komplex wird deprotoniert, AlCl₄⁻ liefert HCl/AlCl₃. ortho-/para-Methoxyacetophenon sind plausible Produkte; exakte Anteile sind offen.','Anisole is plausible. CH₃COCl+AlCl₃ formally gives CH₃CO⁺+AlCl₄⁻; ring pi attacks acyl C and, in the triple-bond contributor, one C≡O pair moves to O. The positive sigma complex deprotonates; AlCl₄⁻ gives HCl/AlCl₃. ortho-/para-methoxyacetophenone are plausible products; exact proportions remain open.'),
('Nitrobenzol ist für klassische Friedel-Crafts stark zu wenig reaktiv. Acylium besitzt keine gewöhnliche Alkylkation-Umlagerung; das gebildete Acylprodukt deaktiviert gegenüber weiteren Substitutionen. Ohne konkrete Temperatur, Komplexierungs- und Produktdaten ist keine exakte ortho/para-Ausbeute festgelegt.','Nitrobenzene is too strongly deactivated for classical Friedel-Crafts. Acylium does not undergo ordinary alkyl-cation rearrangement; the acyl product deactivates further substitution. Without specific temperature, complexation and product data no exact ortho/para yield is fixed.')]),'Eine Syntheseplanung mit zwei Reaktionsvarianten; ob Alkylierung und Acylierung unter planen/steuern ausreichend eng sind, bleibt echte unabhängige Atomaritätsfrage. Kein praktischer Betrieb wird behauptet.')

assert len(profiles)==20 and len(cases)==40
# Explicitly label explanatory model remarks that are not separately requested.
# They remain readable in the answer, but do not add a hidden grading condition.
optional_remarks={
 (1,1,2):('Die Zahl ist eine Näherung dieses Vergleichsmodells.','This value is an approximation of the comparison model.'),
 (2,1,2):('Die einheitlichen Abstände stützen die Delokalisierung; die beiden Bilder allein sind keine Bewegungssimulation.','Uniform distances support delocalization; the pictures are not a simulation of moving bonds.'),
 (2,2,1):('Dies ist ein Stabilitätsargument, keine vollständige kinetische Berechnung.','This is a stability argument, not a complete kinetic calculation.'),
 (5,1,2):('Das erklärt diesen angegebenen Fall, keine universelle Regel für alle protonierten Farbstoffe.','This explains the supplied case rather than a universal rule for all protonated dyes.'),
 (6,1,1):('Das exakte Maximum zwischen Stützstellen ist nicht bestimmt.','An exact maximum between data points is not determined.'),
 (8,1,2):('Die bloße Anzahl von –OH-Gruppen belegt keine stärkere Fixierung an Baumwolle.','Merely counting –OH groups does not establish stronger cotton fixation.'),
 (9,1,1):('Die gelbliche/grünliche Küpenfarbe und spätere Blaufärbung sind Erwartungen, keine hier beobachteten Ergebnisse.','Yellowish/greenish vat color and later blue are predictions, not observed results here.'),
 (12,2,2):('Kein exakter Isomerenanteil folgt daraus.','Exact isomer proportions do not follow.')
}
for (n,k,criterion),remark in optional_remarks.items():
 c=next(c for c in cases if c['goalId']==IDS[n-1] and c['caseId'].endswith(f'-{k}'));r=c['rubric'][criterion-1]
 for lang,txt in zip(['De','En'],remark):
  assert txt in r['criterion'+lang],(n,k,criterion,lang)
  r['criterion'+lang]=r['criterion'+lang].replace(txt,'').strip()
  c['optionalModelRemarks'+lang].append(dict(text=txt,graded=False,criterionId=r['criterionId']))
 for p in profiles:
  if p['goalId']==c['goalId']:
   b=next(b for b in p['profile']['applicationCaseBriefs']if b['id']==c['caseId'])
   for lang,txt in zip(['De','En'],remark):b['understandingFocus'+lang]=b['understandingFocus'+lang].replace(txt,'').strip()
common=dict(schemaVersion=1,license='CC-BY-4.0',authoredAtUTC=datetime.datetime.now(datetime.timezone.utc).isoformat(),goalIds=IDS,currentScientificCompletionsFromAuthoring=0,independentReviews=0)
def write(name,x): (O/'author'/name).write_text(json.dumps(dict(common,**x),ensure_ascii=False,indent=2)+'\n')
write('whole20.profile-payloads.author.json',dict(profiles=profiles))
write('whole40.expanded-cases.author.json',dict(cases=cases))
write('whole20.atomicity-memory-source-boundaries.author.json',dict(records=rationales,newMemoryVotes=0,currentM='Exact current raw rows; no_memory_needed20 retained',sourceClaims='Literal witness/partner inventory is not full-source clearance',currentGoalBodyChanges=[]))
audit=[]
for c in cases:
 for r in c['rubric']:
  audit.append(dict(goalId=c['goalId'],caseId=c['caseId'],criterionId=r['criterionId'],expectationIds=r['expectationIds'],explicitAskedClauseDe=r['taskClauseDe'],explicitAskedClauseEn=r['taskClauseEn'],taskSpanDe=r['taskSpanDe'],taskSpanEn=r['taskSpanEn'],taskClauseFoundDe=c['taskDe'][r['taskSpanDe']['start']:r['taskSpanDe']['end']]==r['taskClauseDe'],taskClauseFoundEn=c['taskEn'][r['taskSpanEn']['start']:r['taskSpanEn']['end']]==r['taskClauseEn'],creditBasis=r['creditBasis'],authorScientificAudit='Exact printed demand maps to this case-specific criterion. Optional comments carry no additional required credit. Practical execution requires direct real observation.'))
write('whole40.case-to-observable-rubric-audit.author.json',dict(records=audit,allCriteriaExplicitlyAsked=all(r['taskClauseFoundDe'] and r['taskClauseFoundEn']for r in audit),unobservedPracticalCriteriaNeverCreditedFromPaper=True,normalTwoDemonstrationSchemaIsEvidenceDesignNotExtraTaskQuota=True,independentReviewPending=True))
print(json.dumps(dict(profiles=len(profiles),cases=len(cases),criteria=len(audit),practicalExecutionCriteria=sum(r['creditBasis']=='observed-practical-execution-required'for r in audit),newScience=0)))
